      [projectId]: {
        generation: (current[projectId]?.generation ?? 0) + 1,
        directory,
      },
    }));
  }, []);

  useEffect(() => {
    document.title = activeEntry ? `${activeEntry.project.name} · ${activeEntry.worktree.branch || 'detached'} · AOW` : 'Project AOW';
  }, [activeEntry]);

  return <div className="project-aow"
