.system-file-uploads li small { color:var(--aow-muted); font-size:10px; }
.system-file-uploads li > span { max-width:40%; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; font-size:11px; }
.system-file-uploads progress { width:100px; height:4px; accent-color:var(--aow-accent); }
.system-file-success { color:var(--aow-success); }
