.system-file-footer > span:first-child { min-width:0; flex:1; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.system-file-drop-overlay { position:absolute; inset:48px 8px 8px; z-index:5; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:12px; padding:24px; color:#dceaff; background:#243b59f0; border:2px dashed var(--aow-accent); border-radius:6px; pointer-events:none; }
