            transcript_path: self.transcript_path.clone(),
            trusted_root: self.trusted_root.clone(),
        }
    }

    pub fn new(
        locator: AgentSessionLocator,
        created_at: DateTime<Utc>,
        updated_at: DateTime<Utc>,
    ) -> Self {
