+async fn simultaneous_triggers_respect_one_stable_concurrency_slot() {
+    use std::os::unix::fs::MetadataExt;
+    let (directory, store, mut task) = fixture(BLOCKED_AGENT);
+    task.input.max_concurrent_runs = 1;
