    assert!(store.is_running(&task.id).unwrap());
    fs::write(release, "done").unwrap();
    assert!(
        tokio::time::timeout(Duration::from_secs(10), process.wait())
            .await
            .unwrap()
            .unwrap()
            .success()
    );
