        fs::read_to_string(store.run_path(&task.id, &id).unwrap().join("events.jsonl")).unwrap();
    assert!(raw.contains("original prompt"));
    assert!(!raw.contains("edited prompt"));
    assert!(!fresh_reader.is_running(&task.id).unwrap());
}

