        })
        .unwrap();
    drop(writer);
    fs::OpenOptions::new()
        .append(true)
        .open(store.run_path(&task.id, &id).unwrap().join("events.jsonl"))
        .unwrap()
        .write_all(b"{\"type\":")
        .unwrap();
