+    pub fn selection(&self) -> ConfigSelection {
+        ConfigSelection {
+            config_repo: self.repository.clone(),
+            config_id: self
+                .directory
+                .file_name()
+                .unwrap()
+                .to_str()
+                .unwrap()
+                .to_owned(),
+        }
+    }
