+async fn sync_remote(repository: impl AsRef<Path>, command: &str) -> Result<(), GitError> {
+    let repository = absolute(repository)?;
+    let output = run_git_with_timeout(
+        &repository,
+        &[command],
+        SMALL_OUTPUT_LIMIT,
+        &[("GIT_TERMINAL_PROMPT", "0"), ("GIT_EDITOR", "true")],
+        Duration::from_secs(120),
+    )
