            "id": registrations[0].id, "agent_type": "traecli", "display_name": "Another wrapper",
            "command": "/bin/sh", "args": ["--custom"]
        })).unwrap()).await.unwrap();
        assert_eq!(updated.agent_type, Some(AgentType::TraeCli));
        assert_eq!(manager.agents().await.unwrap().len(), 4);
    }

