                        .count()
                        % 2,
                    0
                );
                reconstructed.extend(fragment.lines().filter(|line| !line.starts_with(delimiter)));
            }
            let expected: String = text
                .lines()
                .filter(|line| !line.starts_with(delimiter))
                .collect();
