+    let mut response_headers = HeaderMap::new();
+    response_headers.insert(
+        ETAG,
+        HeaderValue::from_str(&format!("\"{}\"", result.version))
+            .map_err(|error| HttpError::internal(error.to_string()))?,
+    );
