+    let mut ids = HashSet::new();
+    let mut hosts = HashSet::new();
+    for p in &settings.providers {
+        if !valid_id(&p.id) || !ids.insert(&p.id) || p.id == "auto" {
+            return Err(PullRequestError::Invalid(
+                "Provider ID 必须唯一，只能包含字母、数字、-、_，且不能为 auto。".into(),
