+    method: &str,
+    path: &str,
+    cookie: Option<&str>,
+    payload: Value,
+) -> Response {
+    let mut request = Request::builder().method(method).uri(path);
+    if let Some(cookie) = cookie {
+        request = request.header(COOKIE, cookie);
+    }
+    app.clone()
+        .oneshot(
+            request
+                .header("content-type", "application/json")
+                .body(Body::from(payload.to_string()))
+                .unwrap(),
+        )
+        .await
+        .unwrap()
