+            match Self::check(connection.socket.next().await)? {
+                Some(TerminalAttachServerMessage::Control {
+                    state: TerminalControlState::Claimed,
+                }) => return Ok(connection),
+                Some(TerminalAttachServerMessage::Control { .. }) => {
