+            Some(Ok(tungstenite::Message::Text(text))) => {
+                let message = serde_json::from_str(&text)?;
+                match message {
+                    TerminalAttachServerMessage::Error { message, .. } => {
+                        Err(TerminalError::Conflict(message))
+                    }
