+#[derive(Clone, Debug, Serialize)]
+pub(crate) struct TaskStopSource {
+    pub(crate) project_name: String,
+    pub(crate) workspace_root: String,
+    pub(crate) tab_id: String,
+    pub(crate) tab_name: String,
