+async fn send_stream_error<S>(
+    sender: &mut S,
+    runtime: &Runtime,
+    owner: Option<ControllerOwner>,
+    code: &str,
+    message: &str,
+) -> bool
+where
+    S: Sink<Message> + Unpin,
