+
+impl WriteBatch {
+    fn new(
+        revision: u64,
+        start_offset: u64,
+        data: &[u8],
+        pending_bytes: &Arc<AtomicUsize>,
+    ) -> Option<Self> {
+        if data.len() > MAX_WRITE_BATCH_BYTES || !reserve_write_bytes(pending_bytes, data.len()) {
+            return None;
+        }
+        Some(Self {
+            revision,
+            start_offset,
+            data: data.to_vec(),
+            pending_bytes: pending_bytes.clone(),
