            );
        }
        let wire = frame(json!({ "protocol_version": 999 }), &[]);
        assert_eq!(
            read_frame(&mut wire.as_slice()).await.err().unwrap().kind(),
            io::ErrorKind::InvalidData
        );
    }
}

