  { id: 'browser', label: '系统文件浏览器', color: '#8fa8bd' },
  { id: 'terminal', label: 'Terminal', color: '#6ca8f1' },
  { id: 'session', label: 'Conversation', color: '#ae9bd7' },
  { id: 'automation', label: '自动化', color: '#c8b480' },
