@media (max-width:900px) { .floating-workspace .system-file-shortcuts { display:none; } .floating-workspace .system-file-body { grid-template-columns:180px minmax(0,1fr); } }

.floating-workspace .system-file-browser[hidden] { display:none; }

.floating-workspace-error { position:absolute; bottom:0; left:0; right:0; z-index:5; display:flex; align-items:center; gap:8px; padding:8px 12px; background:var(--aow-panel); color:#f48771; border-top:1px solid var(--aow-control-line); }
.floating-workspace-error button { margin-left:auto; }
.floating-workspace-error svg { width:16px; height:16px; }

