      ...(agent.id ? { id: agent.id } : {}),
      agent_type: agent.agentType,
      display_name: agent.displayName,
      command: agent.command,
      args: agent.args,
      env: agent.env,
    }),
  }),
  removeAgent: (id: string) => aowRequest<void>(`/api/aow/agents/${encodeURIComponent(id)}`, { method: 'DELETE' }),
};

