  };
  const save = async () => {
    if (!draft) return;
    setBusy(true); setError(''); setStatus('');
    try { const next = await prApi.saveReviewProviders(draft); setDraft(next); setSaved(next); setStatus('Provider 配置和脚本已保存。'); window.dispatchEvent(new Event('aow-review-providers-changed')); }
