    await delay(100);
    release();
    state.detailGate = null;
    state.task = { ...task };
    await delay(100);
    assert.equal(await page.getByRole('heading', { name: 'Stale response', includeHidden: true }).count(), 0);
    await assertResumed(() => tab(page, task.name).dispatchEvent('click'));
  });
