    state.failPins = true;
    await page.clock.runFor(10100);
    await page.locator('[data-error]').filter({ hasText: 'Fixture unavailable' }).waitFor();
    state.failPins = false;
    await page.clock.runFor(10100);
    await page.waitForFunction(() => document.querySelector('[data-error]').textContent === '');
