+    tool('7', 'exec_command'), tool('8', 'wait'),
+  ]), 'Loaded tools, read files, edited files, ran commands');
+  assert.equal(toolSummary([tool('1', 'exec_command', { actions: ['search_files', 'list_files'] })]), 'Searched content, listed files');
