+  assert.equal(toolSummary([tool('1', 'Bash', { actions: ['future_action'] })]), 'Ran commands');
+  assert.equal(toolSummary([tool('1', 'Read'), tool('2', 'unknown_tool')]), 'Read files, called tools');
+});
+
