+function isMain() {
+  if (!process.argv[1]) return false;
+  try {
+    // Node resolves the module's real path, while argv can retain a symlinked HOME.
+    return import.meta.url === pathToFileURL(realpathSync(process.argv[1])).href;
+  } catch {
+    return false;
+  }
