+
+if (isMain()) {
+  try {
+    if (process.argv.length !== 4) throw new Error('Usage: replace-symlink.mjs SOURCE DESTINATION');
+    replaceSymlink(process.argv[2], process.argv[3]);
+  } catch (error) {
+    console.error(`error: ${error.message}`);
+    process.exitCode = 1;
+  }
