+  ? lazy(() =>
+      import("../../frontend/src/mobile/MobileAow").then((module) => ({
+        default: module.MobileAow,
+      })),
+    )
+  : lazy(() =>
+      import("../../frontend/src/aow/ProjectAow").then((module) => ({
+        default: module.ProjectAow,
+      })),
+    );
