    redirected = undefined;
    const missing = new URL(
      `${base}missing/nested/page`,
      "https://example.com",
    );
    missing.replace = location.replace;
    runInNewContext(source, { document, location: missing, URL });
    assert.equal(redirected, undefined);
  }
});

