#[tokio::test]
async fn mount_is_bounded_and_preserves_authentication_and_cookie_scope() {
    let (_root, state) = fixture("/tools/aow");
    let root_app = build_router(state.clone().with_base_path(BasePath::default()));
    let app = build_router(state);
    let redirect = get(&app, "/tools/aow?ui=desktop").await;
    assert_eq!(redirect.headers()[LOCATION], "/tools/aow/?ui=desktop");
    for path in [
        "/api/health",
        "/aow/",
        "/assets/app.js",
        "/tools/aow-other/api/health",
    ] {
        assert_eq!(
            get(&app, path).await.status(),
            StatusCode::NOT_FOUND,
            "{path}"
        );
    }
    for path in [
        "/api/fs/tree",
        "/api/operations/stream",
        "/api/terminals/task-stops",
        "/help",
        "/fs/",
    ] {
        assert_eq!(
            get(&app, &format!("/tools/aow{path}")).await.status(),
            StatusCode::UNAUTHORIZED,
            "{path}"
        );
    }
    // The exact public read route still bypasses login; other API routes do not.
    assert_eq!(
        get(&app, "/tools/aow/api/public/session-shares/missing")
            .await
            .status(),
        StatusCode::NOT_FOUND
    );
    assert_eq!(
        get(&app, "/tools/aow/api/public/session-shares/missing/extra")
            .await
            .status(),
        StatusCode::UNAUTHORIZED
    );
    let login = app
        .clone()
        .oneshot(
            Request::post("/tools/aow/api/auth/login")
                .header("content-type", "application/json")
                .body(Body::from(r#"{"pin":"123456"}"#))
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(login.status(), StatusCode::OK);
    let cookie = login.headers()["set-cookie"].to_str().unwrap();
    assert!(cookie.starts_with("aow_session_"));
    assert!(cookie.contains("Path=/tools/aow/; HttpOnly; SameSite=Strict"));
    let cookie = cookie.split(';').next().unwrap();
    for (router, path, status) in [
        (&app, "/tools/aow/api/fs/tree", StatusCode::OK),
        (&root_app, "/api/fs/tree", StatusCode::UNAUTHORIZED),
    ] {
        let response = router
            .clone()
            .oneshot(
                Request::get(path)
                    .header("cookie", cookie)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), status);
    }
    for (path, expected) in [
        ("/help", "/tools/aow/api/fs/tree"),
        ("/fs/", "/tools/aow/fs/tmp/"),
    ] {
        let response = app
            .clone()
            .oneshot(
                Request::get(format!("/tools/aow{path}"))
                    .header("cookie", cookie)
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        assert!(body(response).await.contains(expected));
    }
}

use std::time::{Duration, Instant};

use anyhow::{Context, Result, anyhow, bail};
use reqwest::{Client, Method, StatusCode};
use serde_json::{Value, json};
use tokio::sync::Mutex;

use super::ImProvider;
use crate::notifications::AutomationFailureNotification;
use crate::terminal::notifications::TaskStopNotification;

mod cards;

const BASE_URL: &str = "https://open.feishu.cn/open-apis";
const TOKEN_PATH: &str = "/auth/v3/tenant_access_token/internal";
const APP_PATH: &str = "/application/v6/applications/me?lang=zh_cn&user_id_type=open_id";
const MESSAGE_PATH: &str = "/im/v1/messages?receive_id_type=open_id";

struct CachedToken {
    value: String,
    refresh_at: Instant,
}

pub(crate) struct FeishuClient {
    http: Client,
    base_url: String,
    app_id: String,
    app_secret: String,
    token: Mutex<Option<CachedToken>>,
    next_delivery: Mutex<Instant>,
}

impl FeishuClient {
    pub(super) fn new(app_id: String, app_secret: String) -> Result<Self> {
        Ok(Self {
            http: Client::builder()
                .connect_timeout(Duration::from_secs(5))
                .timeout(Duration::from_secs(15))
                .redirect(reqwest::redirect::Policy::none())
                .retry(reqwest::retry::never())
                .build()
                .context("无法初始化飞书 HTTP 客户端")?,
            base_url: BASE_URL.to_owned(),
            app_id,
            app_secret,
            token: Mutex::new(None),
            next_delivery: Mutex::new(Instant::now()),
        })
    }

    async fn token(&self) -> Result<String> {
        // Hold the lock across the request: concurrent deliveries share one refresh.
        let mut cached = self.token.lock().await;
        if let Some(token) = cached.as_ref()
            && Instant::now() < token.refresh_at
        {
            return Ok(token.value.clone());
        }
        let started = Instant::now();
        let response = self
            .request(
                Method::POST,
                TOKEN_PATH,
                None,
                Some(&json!({
                    "app_id": self.app_id, "app_secret": self.app_secret,
                })),
            )
            .await?;
        check_code(&response)?;
        let value = response["tenant_access_token"]
            .as_str()
            .filter(|token| !token.is_empty())
            .context("飞书未返回 tenant_access_token")?
            .to_owned();
        let seconds = response["expire"]
            .as_u64()
            .filter(|seconds| *seconds > 0 && *seconds <= 7200)
            .context("飞书返回了无效的 token 有效期")?;
        let margin = 60.min(seconds / 10);
        *cached = Some(CachedToken {
            value: value.clone(),
            refresh_at: started + Duration::from_secs(seconds - margin),
        });
        Ok(value)
    }

    async fn invalidate_token(&self, rejected: &str) {
        let mut cached = self.token.lock().await;
        if cached.as_ref().is_some_and(|token| token.value == rejected) {
            *cached = None;
        }
    }

    async fn authenticated(
        &self,
        method: Method,
        path: &str,
        body: Option<&Value>,
    ) -> Result<Value> {
        for attempt in 0..2 {
            let token = self.token().await?;
            let response = self
                .request(method.clone(), path, Some(&token), body)
                .await?;
            // Only retry when Feishu explicitly rejected the token, never on an
            // ambiguous timeout that could have already delivered the message.
            if matches!(response["code"].as_i64(), Some(99991663 | 99991665)) && attempt == 0 {
                self.invalidate_token(&token).await;
                continue;
            }
            check_code(&response)?;
            return Ok(response);
        }
        unreachable!()
    }

    async fn request(
        &self,
        method: Method,
        path: &str,
        token: Option<&str>,
        body: Option<&Value>,
    ) -> Result<Value> {
        for attempt in 0..2 {
            let mut request = self
                .http
                .request(method.clone(), format!("{}{path}", self.base_url));
            if let Some(token) = token {
                request = request.bearer_auth(token);
            }
            if let Some(body) = body {
                request = request.json(body);
            }
            let response = request.send().await.context("飞书网络请求失败")?;
            let status = response.status();
            let delay = response
                .headers()
                .get("retry-after")
                .and_then(|value| value.to_str().ok())
                .and_then(|value| value.parse::<u64>().ok())
                .unwrap_or(1);
            let bytes = response.bytes().await.context("无法读取飞书响应")?;
            let data = serde_json::from_slice::<Value>(&bytes).ok();
            let limited = status == StatusCode::TOO_MANY_REQUESTS
                || data
                    .as_ref()
                    .is_some_and(|data| matches!(data["code"].as_i64(), Some(99991400 | 230020)));
            if limited {
                if attempt == 0 && delay <= 5 {
                    tokio::time::sleep(Duration::from_secs(delay.max(1))).await;
                    continue;
                }
                bail!("飞书请求受到限流");
            }
            // Feishu may return token errors with HTTP 401/400. Preserve the code
            // for the authentication layer; never log the response body or secrets.
            if let Some(data) = data
                && data["code"].as_i64().is_some()
            {
                if status.is_success() || data["code"].as_i64() != Some(0) {
                    return Ok(data);
                }
            }
            bail!("飞书响应无效（HTTP {}）", status.as_u16());
        }
        unreachable!()
    }

    async fn owner(&self) -> Result<String> {
        let response = self.authenticated(Method::GET, APP_PATH, None).await?;
        let app = &response["data"]["app"];
        if app["owner"]["type"].as_u64() != Some(2) {
            bail!("飞书应用 owner 不是企业内部成员，请配置企业自建应用机器人");
        }
        app["owner"]["owner_id"]
            .as_str()
            .filter(|id| id.starts_with("ou_") && id.len() > 3)
            .map(str::to_owned)
            .context("飞书未返回有效的 owner Open ID")
    }
    async fn send_cards(&self, build: impl FnOnce(&str) -> Result<Vec<Value>>) -> Result<()> {
        // Serialize whole notifications so their parts stay in order. Pace each
        // card below the recipient's 5 QPS limit, including multipart messages.
        let mut next = self.next_delivery.lock().await;
        // Resolve the current owner per delivery, so transferring app ownership
        // never leaves a long-lived cached recipient pointing at the old owner.
        let owner = self.owner().await?;
        let messages = build(&owner)?;
        let total = messages.len();
        for (index, message) in messages.into_iter().enumerate() {
            if let Some(delay) = next.checked_duration_since(Instant::now()) {
                tokio::time::sleep(delay).await;
            }
            *next = Instant::now() + Duration::from_millis(250);
            self.authenticated(Method::POST, MESSAGE_PATH, Some(&message))
                .await
                .with_context(|| format!("飞书卡片发送失败（{}/{total}）", index + 1))?;
        }
        Ok(())
    }
}

impl ImProvider for FeishuClient {
    async fn send_notification(
        &self,
        event: &TaskStopNotification,
        delivery_id: &str,
    ) -> Result<()> {
        self.send_cards(|owner| cards::messages(event, owner, delivery_id))
            .await
    }

    async fn send_automation_failure(
        &self,
        event: &AutomationFailureNotification,
        delivery_id: &str,
    ) -> Result<()> {
        self.send_cards(|owner| Ok(vec![cards::automation_failure(event, owner, delivery_id)?]))
            .await
    }
}

fn check_code(response: &Value) -> Result<()> {
    match response["code"].as_i64() {
        Some(0) => Ok(()),
        Some(code) => {
            let hint = match code {
                99991672 | 99991676 => {
                    "请检查 application:application:self_manage 和 im:message:send_as_bot 权限"
                }
                230013 => "请确认 owner 在应用可用范围内",
                _ => "请检查飞书应用配置及权限",
            };
            Err(anyhow!("飞书接口错误 {code}：{hint}"))
        }
        None => Err(anyhow!("飞书响应缺少状态码")),
    }
}

#[cfg(test)]
mod tests;

//! Display-only JSON 2.0 cards. Size the complete HTTP JSON body, including the
//! second layer of escaping around `content`, against a conservative 30 KB limit.

use std::ops::Range;

use anyhow::{Result, bail, ensure};
use aow_agents::Agent;
use serde_json::{Value, json};

use crate::notifications::AutomationFailureNotification;
use crate::terminal::notifications::TaskStopNotification;

const MAX_REQUEST_BYTES: usize = 28_000;

pub(super) fn automation_failure(
    event: &AutomationFailureNotification,
    owner: &str,
    delivery_id: &str,
) -> Result<Value> {
    let run = &event.run;
    let mut elements = vec![
        plain_text(format!(
            "任务：{}\nAgent：{}\n任务 ID：{}\n执行 ID：{}\n结束时间：{}\n耗时：{}\n退出码：{}",
            run.task_name,
            run.agent.id(),
            run.task_id,
            run.id,
            run.finished_at
                .map(|at| at.to_rfc3339())
                .unwrap_or_else(|| "未知".into()),
            run.duration_ms
                .map(|ms| format!("{:.1} 秒", ms as f64 / 1000.0))
                .unwrap_or_else(|| "未知".into()),
            run.exit_code
                .map(|code| code.to_string())
                .unwrap_or_else(|| "无".into()),
        )),
        plain_text(format!(
            "失败原因：\n{}",
            run.message
                .as_deref()
                .unwrap_or("未记录失败原因")
                .chars()
                .take(2000)
                .collect::<String>()
        )),
    ];
    if let Some(url) = &event.run_url {
        elements.push(json!({"tag":"div","text":{"tag":"lark_md","content":format!("[查看执行记录]({url})")}}));
    }
    let card = json!({
        "schema":"2.0", "config":{"update_multi":true},
        "header":{"title":{"tag":"plain_text","content":format!("自动化失败 · {}", run.task_name)},"template":"red"},
        "body":{"elements":elements}
    });
    let message = json!({"receive_id":owner,"msg_type":"interactive","content":serde_json::to_string(&card)?,"uuid":delivery_id});
    ensure!(
        size(&message)? <= MAX_REQUEST_BYTES,
        "飞书失败提醒超出大小限制"
    );
    Ok(message)
}

pub(super) fn messages(
    event: &TaskStopNotification,
    owner: &str,
    delivery_id: &str,
) -> Result<Vec<Value>> {
    let agent = Agent::from_id(&event.agent)
        .map(|agent| agent.definition().display_name)
        .unwrap_or(&event.agent);
    let mut projects = Vec::new();
    let mut metadata = Vec::new();
    for source in &event.sources {
        let project = source.project_name.trim();
        if !project.is_empty() && !projects.contains(&project) {
            projects.push(project);
        }
        metadata.push(match &source.tab_url {
            Some(url) => json!({"tag":"div","text":{"tag":"lark_md",
                "content":format!("Tab：[{}]({url})", link_label(&source.tab_name))}}),
            None => plain_text(format!("Tab：{}", source.tab_name)),
        });
    }
    let project = if projects.is_empty() {
        "未命名项目".to_owned()
    } else {
        projects.join("、")
    };
    let title = format!("{project}·{}·{agent}·完成", event.title);
    metadata.push(plain_text(format!(
        "会话：{}\nSession ID：{}",
        event.title, event.session_id
    )));
    // Plain text keeps arbitrary labels from becoming Markdown or mentions.
    let metadata = Value::Array(metadata);
    let text = event
        .conclusion
        .as_deref()
        .filter(|text| !text.trim().is_empty())
        .unwrap_or("未捕获到本轮结论。");
    let single = request(&title, &metadata, text, owner, delivery_id, 1, 1)?;
    if size(&single)? <= MAX_REQUEST_BYTES {
        return Ok(vec![single]);
    }

    // There cannot be more parts than UTF-8 bytes. Reserve that many digits in
    // both the header and UUID so learning the final part count cannot overflow.
    let reserve = text.len();
    let fits = |fragment: &str| -> Result<bool> {
        Ok(size(&request(
            &title,
            &metadata,
            fragment,
            owner,
            delivery_id,
            reserve,
            reserve,
        )?)? <= MAX_REQUEST_BYTES)
    };
    ensure!(fits("")?, "飞书通知基础信息过长，无法放入卡片");
    let fences = Fences::parse(text);
    let mut fragments = Vec::new();
    let mut start = 0;
    while start < text.len() {
        // Each source byte costs at least one serialized byte. Search only a
        // request-sized window, even for a conclusion containing a giant line.
        let maximum = (start + MAX_REQUEST_BYTES).min(text.len());
        let boundaries: Vec<usize> = text[start..]
            .char_indices()
            .map(|(offset, _)| start + offset)
            .take_while(|offset| *offset <= maximum)
            .chain((text.len() <= maximum).then_some(text.len()))
            .collect();
        let mut lo = 0;
        let mut hi = boundaries.len();
        while lo + 1 < hi {
            let mid = (lo + hi) / 2;
            if fits(&fences.fragment(text, start..boundaries[mid]))? {
                lo = mid;
            } else {
                hi = mid;
            }
        }
        let mut end = boundaries[lo];
        ensure!(end > start, "飞书通知基础信息过长，无法容纳结论");
        if end < text.len() {
            // Prefer a paragraph, then a whole line, unless that wastes more
            // than half the card. Never trim: every original byte is retained.
            let fragment = &text[start..end];
            if let Some(boundary) = fragment
                .rfind("\n\n")
                .map(|index| index + 2)
                .filter(|index| *index >= fragment.len() / 2)
                .or_else(|| {
                    fragment
                        .rfind('\n')
                        .map(|index| index + 1)
                        .filter(|index| *index >= fragment.len() / 2)
                })
            {
                end = start + boundary;
            }
        }
        // Fence delimiters must remain intact. An exceptionally large delimiter
        // line cannot safely be reformatted; report this instead of losing text.
        if let Some(line) = fences
            .lines
            .iter()
            .find(|line| line.start < end && end < line.end)
        {
            end = line.start;
        }
        ensure!(end > start, "结论中的代码块标记行过长，无法分片");
        let fragment = fences.fragment(text, start..end);
        // A shorter preferred boundary can need a closing fence of its own.
        if !fits(&fragment)? {
            bail!("结论的代码块标记过长，无法放入卡片");
        }
        fragments.push(fragment);
        start = end;
    }
    let total = fragments.len();
    fragments
        .into_iter()
        .enumerate()
        .map(|(index, fragment)| {
            let message = request(
                &title,
                &metadata,
                &fragment,
                owner,
                delivery_id,
                index + 1,
                total,
            )?;
            ensure!(size(&message)? <= MAX_REQUEST_BYTES, "飞书卡片超出大小限制");
            Ok(message)
        })
        .collect()
}

fn plain_text(content: String) -> Value {
    json!({"tag":"div","text":{"tag":"plain_text","content":content}})
}

fn link_label(value: &str) -> String {
    let escaped = value
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;");
    let mut result = String::new();
    for character in escaped.chars() {
        if matches!(character, '\\' | '[' | ']' | '`' | '*' | '_' | '!') {
            result.push('\\');
        }
        result.push(if matches!(character, '\n' | '\r') {
            ' '
        } else {
            character
        });
    }
    result
}

fn size(message: &Value) -> Result<usize> {
    Ok(serde_json::to_vec(message)?.len())
}

fn request(
    title: &str,
    metadata: &Value,
    conclusion: &str,
    owner: &str,
    delivery_id: &str,
    index: usize,
    total: usize,
) -> Result<Value> {
    let title = if total == 1 {
        title.to_owned()
    } else {
        format!("{title} · {index}/{total}")
    };
    let card = json!({
        "schema": "2.0",
        "config": {"update_multi":true, "width_mode":"default"},
        "header": {"title":{"tag":"plain_text","content":title},"template":"blue"},
        "body": {
            "direction":"vertical", "padding":"12px 12px 20px 12px",
            "elements":[
                {"tag":"column_set","flex_mode":"none","columns":[
                    {"tag":"column","width":"weighted","weight":1,
                     "background_style":"grey-50","padding":"12px",
                     "elements":metadata}
                ]},
                {"tag":"markdown","content":"**本轮结论**"},
                {"tag":"markdown","content":conclusion}
            ]
        }
    });
    Ok(json!({
        "receive_id":owner,
        "msg_type":"interactive",
        "content":serde_json::to_string(&card)?,
        // Retries reuse the same ID, different fragments/turns never share it.
        "uuid":if total == 1 { delivery_id.to_owned() } else { format!("{delivery_id}-{index}") }
    }))
}

struct Fence {
    content: Range<usize>,
    opener: String,
    closer: String,
}

#[derive(Default)]
struct Fences {
    spans: Vec<Fence>,
    lines: Vec<Range<usize>>,
}

impl Fences {
    fn parse(text: &str) -> Self {
        let mut result = Self::default();
        let mut open: Option<(u8, usize, usize, String)> = None;
        let mut offset = 0;
        for line in text.split_inclusive('\n') {
            let raw = line.trim_end_matches(['\r', '\n']);
            let trimmed = raw.trim_start_matches(' ');
            let indent = raw.len() - trimmed.len();
            if indent <= 3
                && let Some(marker @ (b'`' | b'~')) = trimmed.bytes().next()
            {
                let count = trimmed.bytes().take_while(|byte| *byte == marker).count();
                if let Some((old_marker, old_count, start, opener)) = &open {
                    if marker == *old_marker
                        && count >= *old_count
                        && trimmed[count..].trim().is_empty()
                    {
                        result.spans.push(Fence {
                            content: *start..offset,
                            opener: opener.clone(),
                            closer: String::from_utf8(vec![marker; *old_count]).unwrap(),
                        });
                        result.lines.push(offset..offset + line.len());
                        open = None;
                    }
                } else if count >= 3 && (marker != b'`' || !trimmed[count..].contains('`')) {
                    open = Some((marker, count, offset + line.len(), raw.to_owned()));
                    result.lines.push(offset..offset + line.len());
                }
            }
            offset += line.len();
        }
        if let Some((marker, count, start, opener)) = open {
            result.spans.push(Fence {
                content: start..text.len(),
                opener,
                closer: String::from_utf8(vec![marker; count]).unwrap(),
            });
        }
        result
    }

    fn fragment(&self, text: &str, range: Range<usize>) -> String {
        let mut result = String::new();
        if let Some(fence) = self.spans.iter().find(|fence| {
            fence.content.start <= range.start
                && range.start <= fence.content.end
                && range.start > 0
        }) {
            result.push_str(&fence.opener);
            result.push('\n');
        }
        result.push_str(&text[range.clone()]);
        if let Some(fence) = self
            .spans
            .iter()
            .find(|fence| fence.content.start <= range.end && range.end <= fence.content.end)
        {
            if !result.ends_with('\n') {
                result.push('\n');
            }
            result.push_str(&fence.closer);
        }
        result
    }
}

