        let app = build_router(AppState::new(frontend));

        let listing = app
            .clone()
            .oneshot(
                Request::get(format!(
                    "/api/fs/tree{}",
                    encode_absolute(&root.path().to_string_lossy())
                ))
                .body(Body::empty())
                .unwrap(),
            )
            .await
            .unwrap();
