        manager
            .inner
            .state
            .lock()
            .unwrap()
            .document
            .im
            .providers
            .len(),
        1
    );
    manager.update(preferences(false, vec![])).unwrap();
    manager
        .update(SettingsUpdate::Im { providers: vec![] })
