import { appUrl } from './lib/basePath';
import { FormEvent, ReactNode, useEffect, useRef, useState } from 'react';

interface AuthStatus {
  configured: boolean;
  authenticated: boolean;
  message?: string;
}

async function authStatus(): Promise<AuthStatus> {
  const response = await fetch(appUrl('/api/auth/status'), { cache: 'no-store' });
  if (!response.ok) throw new Error(`无法读取登录状态（HTTP ${response.status}）`);
  return response.json() as Promise<AuthStatus>;
}

async function login(pin: string): Promise<AuthStatus> {
  const response = await fetch(appUrl('/api/auth/login'), {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ pin }),
  });
  const payload = await response.json().catch(() => null) as { message?: string } | null;
  if (!response.ok) throw new Error(payload?.message ?? `登录失败（HTTP ${response.status}）`);
  return payload as AuthStatus;
}

export function LoginGate({ children }: { children: ReactNode }) {
  const [status, setStatus] = useState<AuthStatus>();
  const [loadError, setLoadError] = useState<string>();

  useEffect(() => {
    let active = true;
    void authStatus()
      .then((next) => { if (active) setStatus(next); })
      .catch((error: unknown) => { if (active) setLoadError(error instanceof Error ? error.message : '无法读取登录状态'); });
    return () => { active = false; };
  }, []);

  if (loadError) return <AuthScreen title="无法连接 AOW" detail={loadError} retry={() => window.location.reload()} />;
  if (!status) return <AuthScreen title="正在检查登录状态…" detail="" />;
  if (!status.configured) return <AuthScreen title="尚未设置访问 PIN" detail={status.message ?? '请在运行 AOW 的服务器上执行 `aow pin`。'} />;
  if (status.authenticated) return <>{children}</>;
  return <PinLogin onSuccess={() => setStatus({ configured: true, authenticated: true })} />;
}

function PinLogin({ onSuccess }: { onSuccess: () => void }) {
  const [pin, setPin] = useState('');
  const [error, setError] = useState<string>();
  const [submitting, setSubmitting] = useState(false);
  const submittingRef = useRef(false);

  const submit = async (pinToSubmit: string) => {
    if (submittingRef.current) return;
    if (!/^\d{6}$/.test(pinToSubmit)) {
      setError('请输入 6 位数字 PIN。');
      return;
    }
    submittingRef.current = true;
    setSubmitting(true);
    setError(undefined);
    try {
      const result = await login(pinToSubmit);
      if (!result.authenticated) throw new Error('登录未完成，请重试。');
      onSuccess();
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : '登录失败，请重试。');
      setPin('');
    } finally {
      submittingRef.current = false;
      setSubmitting(false);
    }
  };

  const onPinChange = (value: string) => {
    const nextPin = value.replace(/\D/g, '').slice(0, 6);
    setPin(nextPin);
    setError(undefined);
    if (nextPin.length === 6) void submit(nextPin);
  };

  const onSubmit = (event: FormEvent) => {
    event.preventDefault();
    void submit(pin);
  };

  return <main className="aow-auth">
    <section className="aow-auth-card" aria-labelledby="aow-auth-title">
      <div className="aow-auth-mark" aria-hidden="true">A<span /></div>
      <p className="aow-auth-eyebrow">AOW</p>
      <h1 id="aow-auth-title">输入访问 PIN</h1>
      <p>请输入服务器管理员设置的 6 位数字 PIN。</p>
      <form onSubmit={onSubmit}>
        <label htmlFor="aow-pin">PIN 码</label>
        <input id="aow-pin" autoComplete="one-time-code" autoFocus inputMode="numeric" maxLength={6} pattern="[0-9]{6}" placeholder="••••••" type="password" value={pin} disabled={submitting} onChange={(event) => onPinChange(event.target.value)} />
        {error && <p className="aow-auth-error" role="alert">{error}</p>}
        <button type="submit" disabled={submitting}>{submitting ? '正在验证…' : '登录'}</button>
      </form>
    </section>
  </main>;
}

function AuthScreen({ title, detail, retry }: { title: string; detail: string; retry?: () => void }) {
  return <main className="aow-auth">
    <section className="aow-auth-card aow-auth-message" aria-live="polite">
      <div className="aow-auth-mark" aria-hidden="true">A<span /></div>
      <p className="aow-auth-eyebrow">AOW</p>
      <h1>{title}</h1>
      {detail && <p>{detail}</p>}
      {retry && <button type="button" onClick={retry}>重试</button>}
    </section>
  </main>;
}

import { appUrl, appBaseUrl } from '../lib/basePath';
import { useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { ChevronDown, ExternalLink } from 'lucide-react';
import { otherNodeAddresses } from './aowNodes';
import './aow-node-switcher.css';

function NodeMenu({ anchor, addresses, mobile, error, onClose }: {
  anchor: HTMLButtonElement;
  addresses?: string[];
  mobile: boolean;
  error?: string;
  onClose: () => void;
}) {
  const menu = useRef<HTMLDivElement>(null);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const nodes = otherNodeAddresses(addresses ?? [], appBaseUrl());
  useLayoutEffect(() => {
    const trigger = anchor.getBoundingClientRect();
    const bounds = menu.current!.getBoundingClientRect();
    setPosition({
      x: Math.max(4, Math.min(trigger.left, window.innerWidth - bounds.width - 4)),
      y: Math.max(4, Math.min(trigger.bottom, window.innerHeight - bounds.height - 4)),
    });
    (menu.current?.querySelector<HTMLAnchorElement>('a') ?? menu.current)?.focus();
  }, [anchor, addresses]);
  useEffect(() => {
    const outside = (event: PointerEvent) => {
      if (!menu.current?.contains(event.target as Node) && !anchor.contains(event.target as Node)) onClose();
    };
    const key = (event: KeyboardEvent) => {
      if (event.key === 'Escape' || event.key === 'Tab') {
        if (event.key === 'Escape') event.preventDefault();
        onClose();
        anchor.focus();
      }
      if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) return;
      event.preventDefault();
      const links = [...menu.current!.querySelectorAll<HTMLAnchorElement>('a')];
      if (!links.length) return;
      const current = links.indexOf(document.activeElement as HTMLAnchorElement);
      const index = event.key === 'Home' ? 0 : event.key === 'End' ? links.length - 1
        : (current + (event.key === 'ArrowDown' ? 1 : -1) + links.length) % links.length;
      links[index].focus();
    };
    window.addEventListener('pointerdown', outside);
    window.addEventListener('resize', onClose);
    window.addEventListener('keydown', key);
    return () => {
      window.removeEventListener('pointerdown', outside);
      window.removeEventListener('resize', onClose);
      window.removeEventListener('keydown', key);
    };
  }, [anchor, onClose]);
  return createPortal(<div ref={menu} id="aow-node-menu" className={`project-aow-context-menu aow-node-menu${mobile ? ' mobile-aow-node-menu' : ''}`}
    style={{ left: position.x, top: position.y }} role="menu" aria-label="其他 AOW 节点" tabIndex={-1}>
    {nodes.map(address => <a key={address} href={address} target="_blank" rel="noopener noreferrer" role="menuitem" title={address} onClick={onClose}>
      <span>{address}</span><ExternalLink aria-hidden="true" />
    </a>)}
    {error ? <p className="aow-node-empty" role="alert">节点地址加载失败：{error}</p>
      : !nodes.length ? <p className="aow-node-empty">{addresses ? '暂无其他节点，可在 Settings → Nodes 中配置。' : '节点地址加载中…'}</p> : null}
  </div>, document.body);
}

export function AowNodeSwitcher({ addresses, mobile = false, error }: { addresses?: string[]; mobile?: boolean; error?: string }) {
  const trigger = useRef<HTMLButtonElement>(null);
  const [open, setOpen] = useState(false);
  const close = useCallback(() => setOpen(false), []);
  return <>
    <button ref={trigger} type="button" className="aow-node-trigger" title="切换 AOW 节点"
      aria-label="切换 AOW 节点" aria-haspopup="menu" aria-expanded={open} aria-controls={open ? 'aow-node-menu' : undefined}
      onClick={() => setOpen(value => !value)} onKeyDown={event => {
        if (event.key === 'ArrowDown' && !open) { event.preventDefault(); setOpen(true); }
      }}>
      <img src={appUrl('/workspace-icon.svg')} width={16} height={16} alt="" aria-hidden="true" draggable={false} />
