    if (!target || !menu.current) return;
    const bounds = menu.current.getBoundingClientRect();
    const x = Math.max(4, Math.min(target.x, window.innerWidth - bounds.width - 4));
    const y = Math.max(4, Math.min(target.y, window.innerHeight - bounds.height - 4));
    if (x !== target.x || y !== target.y) setTarget({ ...target, x, y });
  }, [target]);
  useEffect(() => {
    if (!target) return;
    const close = () => setTarget(undefined);
    window.addEventListener('pointerdown', close);
    window.addEventListener('resize', close);
    window.addEventListener('scroll', close, true);
    const key = (event: KeyboardEvent) => { if (event.key === 'Escape') close(); };
    window.addEventListener('keydown', key);
    return () => { window.removeEventListener('pointerdown', close); window.removeEventListener('resize', close);
      window.removeEventListener('scroll', close, true); window.removeEventListener('keydown', key); };
  }, [target]);
  return <ListRowMenuContext.Provider value={{ target: target?.element, open }}><div className="workspace-open-boundary" onContextMenuCapture={event => {
    const element = (event.target as HTMLElement).closest<HTMLElement>('[data-workspace-open]');
    if (!element) return;
    event.preventDefault(); event.stopPropagation();
    const bounds = element.getBoundingClientRect();
    open(element, event.clientX || bounds.x, event.clientY || bounds.bottom);
  }}>{children}{target ? <div ref={menu} className="project-aow-context-menu" role="menu" aria-label="选择打开位置"
    style={{ left: target.x, top: target.y }} onPointerDown={event => event.stopPropagation()} onMouseDown={event => event.preventDefault()}>
    <button role="menuitem" onClick={() => { target.element.click(); setTarget(undefined); }}><WorkspaceMenuLabel action="open" /></button>
    <button role="menuitem" onClick={() => { withFloatingOpen(() => target.element.click()); setTarget(undefined); }}><WorkspaceMenuLabel action="floating" /></button>
  </div> : null}</div></ListRowMenuContext.Provider>;
}

import { automationApi } from '../../features/automations/api';
import type { TabRouteAdapter, TabTarget } from './types';
import { length, required, segment, url } from './helpers';
export const automationRoute: TabRouteAdapter<Extract<TabTarget, { type: 'automation' }>> = {
  type: 'automation',
  centerId: t => 'automation:' + t.taskId,
  parse(parts, q) {
    if (parts.length === 4 && parts[2] === 'runs') segment(parts, 3); else length(parts, 2);
    return { type: 'automation', workspace: required(q, 'workspace'), taskId: segment(parts, 1),
      runId: parts[3], view: parts[3] || q.get('view') === 'runs' ? 'runs' : undefined };
  },
  url: t => url('automation/' + encodeURIComponent(t.taskId) + (t.runId ? '/runs/' + encodeURIComponent(t.runId) : ''),
    { workspace: t.workspace, view: !t.runId ? t.view : undefined }),
  capture(c) {
    if (!c.tab?.id.startsWith('automation:')) return;
    const location = c.automationLocations[c.tab.targetId];
    return { type: 'automation', workspace: c.workspace, taskId: c.tab.targetId,
      runId: location?.runId, view: location?.view === 'runs' ? 'runs' : undefined };
  },
  async resolve(t, context) {
    const task = await automationApi.detail(t.taskId);
    if (task.project_id !== context.project.id) throw new Error('自动化任务不属于该工作区的项目。');
    if (t.runId) await automationApi.runDetail(t.taskId, t.runId);
    return { task };
  },
  open: (t, resolved, actions) => actions.automation(resolved.task!, { view: t.view ?? 'overview', runId: t.runId }),
};

import type { OpenDocument } from '../../features/editor/types';
import type { TabRouteAdapter, TabTarget } from './types';
import { absolutePath, length, required, url } from './helpers';
export const diffRoute: TabRouteAdapter<Extract<TabTarget, { type: 'diff' }>> = {
  type: 'diff',
  centerId: t => 'document:' + diffDocument(t).id,
  parse(parts, q) {
    length(parts, 1);
    const source = required(q, 'source');
    if (source !== 'working' && source !== 'staged' && source !== 'commit') throw new Error('无法识别 Diff 来源。');
    const commit = source === 'commit' ? required(q, 'commit') : undefined;
    if (commit && !/^[a-f0-9]{40,64}$/i.test(commit)) throw new Error('Commit Diff 必须使用完整提交 SHA。');
    return { type: 'diff', workspace: required(q, 'workspace'), repository: absolutePath(required(q, 'repository')),
      path: required(q, 'path'), source, commit, originalPath: q.get('original_path') ?? undefined, untracked: q.get('untracked') === '1' || undefined };
  },
  url: t => url('diff', { workspace: t.workspace, repository: t.repository, path: t.path, source: t.source,
    commit: t.commit, original_path: t.originalPath, untracked: t.untracked ? '1' : undefined }),
  capture(c) {
    const document = c.documents.find(d => c.tab?.id === 'document:' + d.id);
    const source = document?.diffSource;
    if (!source || !document) return;
    return { type: 'diff', workspace: c.workspace, repository: source.repository, path: document.path,
      ...(source.kind === 'commit' ? { source: 'commit' as const, commit: source.commit, originalPath: source.originalPath }
        : { source: source.staged ? 'staged' as const : 'working' as const, untracked: source.untracked || undefined }) };
  },
  resolve: async () => ({}),
  open: (t, _, actions) => actions.diff(t),
};


export function diffDocument(t: Extract<TabTarget, { type: 'diff' }>): OpenDocument {
  const source: OpenDocument['diffSource'] = t.source === 'commit'
    ? { kind: 'commit', repository: t.repository, commit: t.commit!, originalPath: t.originalPath }
    : { kind: 'working', repository: t.repository, staged: t.source === 'staged', untracked: !!t.untracked };
  return { id: t.source === 'commit' ? `commit-diff:${t.repository}:${t.commit}:${t.path}` : `diff:${t.repository}:${t.source === 'staged'}:${t.path}`,
    path: t.path, name: `${t.path.split('/').pop()} (${t.source === 'commit' ? t.commit!.slice(0, 8) : 'Diff'})`, kind: 'diff', readOnly: true, loading: true, diffSource: source };
}

import type { DocumentSource } from '../../features/editor/types';
import type { TabRouteAdapter, TabTarget } from './types';
import { absolutePath, length, required, url } from './helpers';
const sources = new Set<DocumentSource>(['project', 'notes', 'external']);
export const filesRoute: TabRouteAdapter<Extract<TabTarget, { type: 'files' }>> = {
  type: 'files',
  centerId: () => 'system-files',
  parse(parts, q) { length(parts, 1); return { type: 'files', workspace: required(q, 'workspace'), path: absolutePath(required(q, 'path')) }; },
  url: t => url('files', { workspace: t.workspace, path: t.path }),
  capture: c => c.tab?.kind === 'browser' && c.browserPath ? { type: 'files', workspace: c.workspace, path: c.browserPath } : undefined,
  resolve: async () => ({}),
  open: (t, _, actions) => actions.files(t.path),
};
export const fileRoute: TabRouteAdapter<Extract<TabTarget, { type: 'file' }>> = {
  type: 'file',
  centerId: t => 'document:' + t.path,
  parse(parts, q) {
    length(parts, 1);
    const source = (q.get('source') ?? 'project') as DocumentSource;
    if (!sources.has(source)) throw new Error('无法识别文件来源。');
    return { type: 'file', workspace: required(q, 'workspace'), path: absolutePath(required(q, 'path')), source };
  },
  url: t => url('file', { workspace: t.workspace, path: t.path, source: t.source }),
  capture(c) {
    const document = c.documents.find(d => c.tab?.id === 'document:' + d.id);
    return document && !document.diffSource ? { type: 'file', workspace: c.workspace, path: document.path, source: document.explorerSource ?? 'external' } : undefined;
  },
  resolve: async () => ({}),
  open: (t, _, actions) => actions.file(t.path, t.source),
};

import { appUrl } from '../../lib/basePath';
export const prefix = appUrl('/aow/tabs/');
export function required(query: URLSearchParams, key: string) {
  const value = query.get(key);
  if (!value || value.includes('\0')) throw new Error(`Tab 链接缺少有效的 ${key} 参数。`);
  return value;
}
export function absolutePath(value: string) {
  if (!value.startsWith('/') || value.includes('\0')) throw new Error('Tab 链接中的路径必须为绝对路径。');
  return value;
}
export function segment(segments: string[], index: number) {
  const value = segments[index];
  if (!value || value.includes('\0')) throw new Error('Tab 链接缺少资源标识。');
  return value;
}
export function length(segments: string[], expected: number) {
  if (segments.length !== expected) throw new Error('无法识别此 Tab 链接。');
}
export function url(path: string, params: Record<string, string | undefined>) {
  const query = new URLSearchParams();
  Object.entries(params).forEach(([key, value]) => { if (value !== undefined) query.set(key, value); });
  return prefix + path + (query.size ? '?' + query : '');
}

import { appUrl } from '../../lib/basePath';
import { terminalApi } from '../../features/terminals/terminalApi';
import { aowApi } from '../aowApi';
import type { ResolvedTab, TabContext, TabOpenActions, TabRouteAdapter, TabTarget } from './types';
import { terminalRoute } from './terminal';
import { fileRoute, filesRoute } from './files';
import { diffRoute } from './diff';
import { prRoute } from './pr';
import { sessionRoute } from './session';
import { automationRoute } from './automation';
import { prefix } from './helpers';
export type { TabTarget, ResolvedTab, TabOpenActions, AutomationLocation } from './types';

// The registry is the only dispatch point; each adapter owns its typed payload.
const adapters = [terminalRoute, filesRoute, fileRoute, diffRoute, prRoute, sessionRoute, automationRoute] as TabRouteAdapter[];
const registry = new Map(adapters.map(adapter => [adapter.type, adapter]));
export function parseTabUrl(url: URL): TabTarget | undefined {
  if (!url.pathname.startsWith(prefix)) return;
  const parts = url.pathname.slice(prefix.length).replace(/\/$/, '').split('/').map(decodeURIComponent);
  const adapter = registry.get(parts[0] as TabTarget['type']);
  if (adapter) return adapter.parse(parts, url.searchParams);
  if (parts.length === 1 && parts[0]) return { type: 'terminal', tabId: parts[0] }; // Legacy notification links.
  throw new Error('无法识别此 Tab 链接。');
}
export const tabTargetUrl = (target: TabTarget) => registry.get(target.type)!.url(target);
export const aowTabUrl = (tabId: string) => tabTargetUrl({ type: 'terminal', tabId });
export function captureTabTarget(context: TabContext) {
  for (const adapter of adapters) {
    const target = adapter.capture(context);
    if (target) return target;
  }
}
export async function resolveTabTarget(target: TabTarget, signal: AbortSignal): Promise<ResolvedTab> {
  const terminal = target.type === 'terminal' ? await terminalApi.get(target.tabId, signal) : undefined;
  const projects = await aowApi.projects();
  signal.throwIfAborted();
  const contexts = projects.flatMap(project => project.worktrees.map(worktree => ({ project, worktree })));
  const context = contexts.find(({ worktree }) => terminal ? worktree.path === terminal.workspace_root : worktree.id === (target as Exclude<TabTarget, { type: 'terminal' }>).workspace);
  if (!context) throw new Error('目标 Tab 所属工作区不存在或已被移除。');
  const resolved = await registry.get(target.type)!.resolve(target, context, signal);
  signal.throwIfAborted();
  return { target, workspacePath: context.worktree.path, terminal, ...resolved };
}
export const openTabTarget = (resolved: ResolvedTab, actions: TabOpenActions) =>
  registry.get(resolved.target.type)!.open(resolved.target, resolved, actions);
export function tabLocationUrl(target?: TabTarget, hash = '', search = window.location.search) {
  const url = new URL(target ? tabTargetUrl(target) : appUrl('/aow/'), window.location.origin);
  const existing = new URLSearchParams(search);
  // UI mode is page-level; resource parameters always come from the active Tab.
  if (existing.has('ui')) url.searchParams.set('ui', existing.get('ui')!);
  url.hash = hash;
  return url.pathname + url.search + url.hash;
}


export const tabCenterId = (target: TabTarget) => registry.get(target.type)!.centerId(target);

import type { MobileRoute } from '../../mobile/mobileState';
import type { TabTarget, ResolvedTab } from './types';
import type { AowAgentSession } from '../../features/sessions/types';
import type { AowProject, AowWorktree } from '../types';

type MobileContext = { route: Partial<MobileRoute>; project: AowProject; worktree: AowWorktree };
interface MobileAdapter {
  restore: (target: TabTarget) => Partial<MobileRoute>;
  capture: (context: MobileContext) => TabTarget | undefined;
}
// These adapters translate the same resource routes into the existing mobile readers.
const adapters: Record<TabTarget['type'], MobileAdapter> = {
  terminal: {
    restore: t => t.type === 'terminal' ? { view: 'terminal', terminal: t.tabId } : {},
    capture: () => undefined, // The terminal pane reports its active Tab after loading.
  },
  files: {
    restore: t => t.type === 'files' ? { view: 'files', directory: t.path, fileSource: 'external' } : {},
    capture: ({ route: r, worktree: w, project: p }) => r.view === 'files' && !r.file ? { type: 'files', workspace: w.id, path: r.directory ?? (r.notes === '1' ? p.notes_path : w.path) } : undefined,
  },
  file: {
    restore: t => t.type === 'file' ? { view: 'files', file: t.path, directory: t.path.slice(0, t.path.lastIndexOf('/')) || '/', fileSource: t.source, notes: t.source === 'notes' ? '1' : undefined } : {},
    capture: ({ route: r, worktree: w }) => r.view === 'files' && r.file ? { type: 'file', workspace: w.id, path: r.file, source: r.fileSource ?? (r.notes === '1' ? 'notes' : 'project') } : undefined,
  },
  diff: {
    restore: t => t.type === 'diff' ? { view: 'git', diff: t.path, repository: t.repository, staged: t.source === 'staged' ? '1' : undefined, commit: t.commit, originalPath: t.originalPath, untracked: t.untracked ? '1' : undefined } : {},
    capture: ({ route: r, worktree: w }) => r.view === 'git' && r.diff ? { type: 'diff', workspace: w.id, path: r.diff, repository: r.repository ?? w.path, source: r.commit ? 'commit' : r.staged === '1' ? 'staged' : 'working', commit: r.commit, originalPath: r.originalPath, untracked: r.untracked === '1' || undefined } : undefined,
  },
  pr: {
    restore: t => t.type === 'pr' ? { view: 'pull-requests', pr: String(t.number), provider: t.provider, remote: t.remote, repository: t.repository } : {},
    capture: ({ route: r, worktree: w }) => r.view === 'pull-requests' && r.pr ? { type: 'pr', workspace: w.id, repository: r.repository ?? w.path, provider: r.provider ?? 'auto', remote: r.remote, number: Number(r.pr) } : undefined,
  },
  session: {
    restore: t => t.type === 'session' ? { view: 'sessions', session: t.agent + ':' + t.sessionId, agent: t.agent, cwd: t.cwd } : {},
    capture: ({ route: r, worktree: w }) => r.view === 'sessions' && r.session && r.agent ? { type: 'session', workspace: w.id, agent: r.agent as AowAgentSession['agent'], sessionId: r.session.startsWith(r.agent + ':') ? r.session.slice(r.agent.length + 1) : r.session, cwd: r.cwd ?? w.path } : undefined,
  },
  automation: {
    restore: t => t.type === 'automation' ? { view: 'automations', task: t.taskId, run: t.runId, automationView: t.view } : {},
    capture: ({ route: r, worktree: w }) => r.view === 'automations' && r.task ? { type: 'automation', workspace: w.id, taskId: r.task, runId: r.run, view: r.run || r.automationView === 'runs' ? 'runs' : undefined } : undefined,
  },
};
export function mobileRouteForTab(entry: ResolvedTab): MobileRoute {
  return { workspace: entry.workspacePath, view: 'terminal', ...adapters[entry.target.type].restore(entry.target) };
}
export function mobileTabTarget(route: Partial<MobileRoute>, projects: AowProject[]) {
  const project = projects.find(p => p.worktrees.some(w => w.path === route.workspace));
  const worktree = project?.worktrees.find(w => w.path === route.workspace);
  if (!project || !worktree) return;
  for (const adapter of Object.values(adapters)) {
    const target = adapter.capture({ route, project, worktree });
    if (target) return target;
  }
}

import { prApi } from '../../features/pr/api';
import type { ReviewIdentity } from '../../features/pr/types';
import type { TabRouteAdapter, TabTarget } from './types';
import { absolutePath, length, required, segment, url } from './helpers';
export const prTabId = (repository: string, number: number, target?: ReviewIdentity) =>
  'pull-request:' + encodeURIComponent(repository) + ':' + number +
  (target?.provider && target.provider !== 'auto' || target?.remote ? ':' + encodeURIComponent(target?.provider ?? 'auto') + ':' + encodeURIComponent(target?.remote ?? '') : '');
export const prRoute: TabRouteAdapter<Extract<TabTarget, { type: 'pr' }>> = {
  type: 'pr',
  centerId: t => prTabId(t.repository, t.number, t),
  parse(parts, q) {
    length(parts, 3);
    const provider = segment(parts, 1);
    const number = Number(segment(parts, 2));
    if (!Number.isSafeInteger(number) || number <= 0) throw new Error('PR 编号无效。');
    return { type: 'pr', workspace: required(q, 'workspace'), repository: absolutePath(required(q, 'repository')), provider, number, remote: q.get('remote') || undefined };
  },
  url: t => url('pr/' + encodeURIComponent(t.provider) + '/' + t.number, { workspace: t.workspace, repository: t.repository, remote: t.remote }),
  capture(c) {
    if (c.tab?.kind !== 'pullRequest') return;
    const pr = c.pullRequests.find(r => prTabId(r.repository ?? c.workspacePath, r.number, r) === c.tab?.id);
    return pr ? { type: 'pr', workspace: c.workspace, repository: pr.repository ?? c.workspacePath, provider: pr.provider ?? 'auto', remote: pr.remote, number: pr.number } : undefined;
  },
  async resolve(t) {
    const pr = await prApi.myPullRequest(t.repository, t.number, t);
    return { target: { ...t, provider: pr.provider ?? t.provider, remote: pr.remote ?? t.remote }, pullRequest: { ...pr, provider: pr.provider ?? t.provider, remote: pr.remote ?? t.remote } };
  },
  open: (t, resolved, actions) => actions.pullRequest(resolved.pullRequest!, t.repository),
};

import { sessionsApi } from '../../features/sessions/api';
import type { AowAgentSession } from '../../features/sessions/types';
import type { TabRouteAdapter, TabTarget } from './types';
import { absolutePath, length, required, segment, url } from './helpers';
export const sessionRoute: TabRouteAdapter<Extract<TabTarget, { type: 'session' }>> = {
  type: 'session',
  centerId: t => 'session:' + t.agent + ':' + t.sessionId,
  parse(parts, q) {
    length(parts, 3);
    const agent = segment(parts, 1) as AowAgentSession['agent'];
    return { type: 'session', workspace: required(q, 'workspace'), agent, sessionId: segment(parts, 2),
      cwd: absolutePath(required(q, 'cwd')), taskId: q.get('task') ?? undefined, runId: q.get('run') ?? undefined };
  },
  url: t => url('session/' + encodeURIComponent(t.agent) + '/' + encodeURIComponent(t.sessionId), {
    workspace: t.workspace, cwd: t.cwd, task: t.taskId, run: t.runId }),
  capture(c) {
    const preview = c.sessions.find(s => c.tab?.id === 'session:' + s.session.id);
    return preview ? { type: 'session', workspace: c.workspace, agent: preview.session.agent, sessionId: preview.session.session_id,
      cwd: preview.workspacePath, taskId: preview.automationRun?.taskId, runId: preview.automationRun?.runId } : undefined;
  },
  async resolve(t) {
    const session = t.taskId && t.runId ? await sessionsApi.automationRunSession(t.taskId, t.runId)
      : (await sessionsApi.agentSessions(t.cwd, t.agent)).find(s => s.session_id === t.sessionId);
    if (!session || session.agent !== t.agent || session.session_id !== t.sessionId) throw new Error('该 Conversation Session 已不存在或无法读取。');
    return { session, target: { ...t, cwd: session.cwd, taskId: undefined, runId: undefined } };
  },
  open: (_, resolved, actions) => actions.session(resolved.session!, resolved.session!.cwd),
};

import type { TabRouteAdapter, TabTarget } from './types';
import { length, segment, url } from './helpers';
export const terminalRoute: TabRouteAdapter<Extract<TabTarget, { type: 'terminal' }>> = {
  type: 'terminal',
  centerId: t => 'terminal:' + t.tabId,
  parse(parts) { length(parts, 2); return { type: 'terminal', tabId: segment(parts, 1) }; },
  url: target => url('terminal/' + encodeURIComponent(target.tabId), {}),
  capture: ({ tab }) => tab?.id.startsWith('terminal:') ? { type: 'terminal', tabId: tab.targetId } : undefined,
  resolve: async () => ({}),
  open: (target, _, actions) => actions.terminal(target.tabId),
};

import type { AutomationTask } from '../../features/automations/types';
