import { useCallback, useEffect, useRef } from 'react';
import { gitApi } from './api';
import type { GitLog, GitStatus } from './types';

type RefreshTarget = 'all' | 'changes' | 'commits';
interface Callbacks {
  status: (status: GitStatus) => void;
  log: (log: GitLog) => void;
  error: (message: string) => void;
}

// One round per visible panel. Manual requests and save notifications share
// the same queue; a slow round never accumulates interval ticks.
export function useSourceControlPolling(repository: string, visible: boolean, generation: number, callbacks: Callbacks) {
  const latest = useRef({ repository, visible, callbacks });
  latest.current = { repository, visible, callbacks };
  const refreshRef = useRef<(mask: number) => void>(() => {});
  const previousGeneration = useRef(generation);

  useEffect(() => {
    if (!repository || !visible) return;
    let disposed = false;
    let timer: number | undefined;
    let controller: AbortController | undefined;
    let pending = 0;
    const errors = new Map<number, string>();
    const active = () => !disposed && latest.current.visible
      && latest.current.repository === repository && document.visibilityState === 'visible';
    const clearTimer = () => { window.clearTimeout(timer); timer = undefined; };
    const refresh = async (mask: number) => {
      if (!active()) return;
      clearTimer();
      if (controller) { pending |= mask; return; }
      const request = new AbortController();
      controller = request;
      const run = async <T,>(key: number, load: () => Promise<T>, apply: (value: T) => void) => {
        try {
          const result = await load();
          if (!active() || request.signal.aborted) return;
          apply(result);
          errors.delete(key);
        } catch (reason) {
          if (!active() || request.signal.aborted) return;
          errors.set(key, `${key === 1 ? 'Changes' : 'Commits'}：${reason instanceof Error ? reason.message : String(reason)}`);
        }
      };
      await Promise.all([
        mask & 1 ? run(1, () => gitApi.gitStatus(repository, request.signal), (value) => latest.current.callbacks.status(value)) : undefined,
        mask & 2 ? run(2, () => gitApi.gitLog(repository, request.signal), (value) => latest.current.callbacks.log(value)) : undefined,
      ]);
      controller = undefined;
      if (!active()) return;
      if (!request.signal.aborted) latest.current.callbacks.error([...errors.values()].join('；'));
      if (pending) {
        const next = pending; pending = 0;
        void refresh(next);
      } else {
        timer = window.setTimeout(() => void refresh(3), 5_000);
      }
    };
    const onVisibilityChange = () => {
      clearTimer();
      if (document.visibilityState === 'visible') void refresh(3);
      else { pending = 0; controller?.abort(); }
    };
    refreshRef.current = (mask) => void refresh(mask);
    document.addEventListener('visibilitychange', onVisibilityChange);
    void refresh(3);
    return () => {
      disposed = true;
      refreshRef.current = () => {};
      clearTimer();
      controller?.abort();
      document.removeEventListener('visibilitychange', onVisibilityChange);
    };
  }, [repository, visible]);

  useEffect(() => {
    if (previousGeneration.current !== generation) refreshRef.current(3);
    previousGeneration.current = generation;
  }, [generation]);

  return useCallback((target: RefreshTarget = 'all') => refreshRef.current(target === 'changes' ? 1 : target === 'commits' ? 2 : 3), []);
}

import { appUrl } from '../../lib/basePath';
import { useEffect, useId, useRef, useState } from 'react';
import { ChevronDown, ChevronUp, Layers, X } from 'lucide-react';
import './agent-task-notifications.css';
import { useAowTerminalTabActivity, useAowTabNavigation } from '../../aow/AowTabEntry';
import { parseTaskStop, taskNotifications, useTaskNotifications, type TaskNotice } from './taskNotifications';
import { AgentIcon } from '../agents/AgentIcon';

const agentNames: Record<string, string> = { codex: 'Codex', traecli: 'TraeCode CLI', claude: 'Claude Code' };
const visibleNoticeCount = 5;

function TaskNoticeCard({ notice }: { notice: TaskNotice }) {
  const navigateTab = useAowTabNavigation();
  const [error, setError] = useState('');
  const [opening, setOpening] = useState(false);
  const sources = notice.sources.filter(source => source.tab_id);
  const projectName = [...new Set(sources.map(source => source.project_name || source.workspace_root.split('/').filter(Boolean).pop() || '未命名项目'))].join('、')
    || notice.cwd.split('/').filter(Boolean).pop() || '未命名项目';
  const tabName = [...new Set(sources.map(source => source.tab_name || '未命名 Tab'))].join('、') || 'Tab 不可用';
  const failure = error || (!sources.length ? '无法定位对应 Tab。' : '');
  const dismiss = () => taskNotifications.dismiss(item => item.key === notice.key);
  const open = async () => {
    if (opening) return;
    setOpening(true);
    setError('');
    // A session may have several source tabs. Open the first one still available.
    let message = '';
    for (const source of sources) {
      try {
        await navigateTab({ type: 'terminal', tabId: source.tab_id });
        dismiss();
        setOpening(false);
        return;
      } catch (reason) { message = reason instanceof Error ? reason.message : String(reason); }
    }
    setError(message);
    setOpening(false);
  };
  return <article className="agent-task-notice" role="status">
    <button type="button" className="agent-task-notice-open" aria-label={`打开通知：${projectName} · ${tabName}`}
      disabled={opening || !sources.length} aria-busy={opening} onClick={() => void open()}>
      <span className="agent-task-notice-agent" title={agentNames[notice.agent] ?? notice.agent}><AgentIcon agentId={notice.agent} /></span>
      <span className="agent-task-notice-content">
        <span className="agent-task-notice-heading"><strong title={projectName}>{projectName}</strong>
          <time dateTime={new Date(notice.receivedAt).toISOString()} title={new Date(notice.receivedAt).toLocaleString()}>
            {new Date(notice.receivedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
          </time>
        </span>
        <span className="agent-task-notice-tab" title={tabName}>{tabName}</span>
      </span>
    </button>
    <button type="button" className="agent-task-notice-close" aria-label={`关闭通知：${projectName} · ${tabName}`}
      title="关闭弹框，保留未读提醒" disabled={opening}
      onClick={() => taskNotifications.closePopups(item => item.key === notice.key)}><X size={14} aria-hidden="true" /></button>
    {failure && <div className="agent-task-notice-failure">
      <span className="agent-task-notice-error" role="alert">{failure}</span>
      <button type="button" className="agent-task-notice-remove" onClick={dismiss}>移除通知</button>
    </div>}
  </article>;
}

export function AgentTaskNotifications() {
  const { notices: unreadNotices, storageError } = useTaskNotifications();
  const notices = unreadNotices.filter(notice => !notice.popupClosed);
  const [expanded, setExpanded] = useState(false);
  const tabActivity = useAowTerminalTabActivity();
  const listId = useId();
  const list = useRef<HTMLDivElement>(null);

  useEffect(() => { if (!notices.length) setExpanded(false); }, [notices.length]);

  useEffect(() => {
    const dismissActive = () => {
      const tabId = tabActivity.getCurrent();
      if (tabId) taskNotifications.dismiss(notice => notice.sources.some(source => source.tab_id === tabId));
    };
    dismissActive();
    return tabActivity.subscribe(dismissActive);
  }, [tabActivity]);

  useEffect(() => {
    const source = new EventSource(appUrl('/api/terminals/task-stops'));
    const stopped = (event: MessageEvent<string>) => {
      let notice;
      try { notice = parseTaskStop(JSON.parse(event.data)); } catch { return; }
      if (!notice) return;
      if (notice.sources.some(source => source.tab_id === tabActivity.getCurrent())) return;
      // This is a live callback, not session-level deduplication: every newly
      // consumed stop record gets its own notice, including subsequent turns.
      taskNotifications.add(notice);
    };
    source.addEventListener('task-stopped', stopped);
    return () => { source.removeEventListener('task-stopped', stopped); source.close(); };
  }, [tabActivity]);

  if (!notices.length) return null;
  const visibleNotices = expanded ? notices : notices.slice(0, visibleNoticeCount);
  const foldedCount = notices.length - visibleNoticeCount;
  const collapse = () => { setExpanded(false); list.current?.scrollTo({ top: 0 }); };
  return <section className={`agent-task-notifications${expanded ? ' is-expanded' : ''}`} aria-label="任务完成提醒"
    onKeyDown={event => { if (expanded && event.key === 'Escape') { event.stopPropagation(); collapse(); } }}>
    {(notices.length > 1 || expanded) && <div className="agent-task-notifications-toolbar">
      <span>{notices.length} 条待处理</span>
      {expanded && <button onClick={collapse} aria-expanded="true" aria-controls={listId}><ChevronUp size={14} />收起</button>}
      {notices.length > 1 && <button className="agent-task-notifications-clear" title="关闭全部弹框，保留未读提醒" onClick={() => taskNotifications.closePopups(() => true)}>全部关闭</button>}
    </div>}
    {storageError && <div className="agent-task-notifications-storage-error" role="alert">{storageError}</div>}
    <div className="agent-task-notifications-list" id={listId} ref={list} tabIndex={expanded ? 0 : undefined}
      aria-label="待处理通知" aria-live="polite" aria-relevant="additions">
      {visibleNotices.map(notice => <TaskNoticeCard key={notice.key} notice={notice} />)}
    </div>
    {!expanded && foldedCount > 0 && <button className="agent-task-notifications-stack" aria-expanded="false" aria-controls={listId}
      onClick={() => { setExpanded(true); list.current?.scrollTo({ top: 0 }); }}>
      <Layers size={18} aria-hidden="true" /><span><strong>还有 {foldedCount} 条通知</strong><small>展开查看全部</small></span><ChevronDown size={16} aria-hidden="true" />
    </button>}
  </section>;
}

import { appBaseUrl } from '../../lib/basePath';
import { useEffect, useState } from 'react';
import { notificationsApi } from './api';
import type { NotificationChannel, NotificationSettings, NotificationSettingsUpdate, TaskCompletedSettings } from './types';
import './notification-settings.css';

export function NotificationSettingsPanel({ section, onBusyChange }: {
  section: 'im' | 'notifications'; onBusyChange: (busy: boolean) => void;
}) {
  const [settings, setSettings] = useState<NotificationSettings>();
  const [appId, setAppId] = useState('');
  const [secret, setSecret] = useState('');
  const [task, setTask] = useState<TaskCompletedSettings>({ enabled: true, channels: ['page'] });
  const [publicBaseUrl, setPublicBaseUrl] = useState('');
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [saved, setSaved] = useState('');
  const feishu = settings?.im.providers.find(provider => provider.provider === 'feishu');

  useEffect(() => {
    let active = true;
    void notificationsApi.notificationSettings().then(next => {
      if (!active) return;
      setSettings(next);
      setAppId(next.im.providers.find(provider => provider.provider === 'feishu')?.app_id ?? '');
      setTask(next.notifications.agent_task_completed);
      setPublicBaseUrl(next.notifications.public_base_url ?? '');
    }).catch(reason => { if (active) setError(reason instanceof Error ? reason.message : String(reason)); })
      .finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, []);

  useEffect(() => { setError(''); setSaved(''); }, [section]);

  const changed = () => { setError(''); setSaved(''); };
  const save = async (update: NotificationSettingsUpdate) => {
    setBusy(true); onBusyChange(true); changed();
    try {
      const next = await notificationsApi.updateNotificationSettings(update);
      setSettings(next);
      if (update.section === 'im') {
        setAppId(next.im.providers.find(provider => provider.provider === 'feishu')?.app_id ?? '');
        setSecret('');
      } else {
        setTask(next.notifications.agent_task_completed);
        setPublicBaseUrl(next.notifications.public_base_url ?? '');
      }
      setSaved(update.section === 'im' ? 'IM 配置已保存。' : '通知配置已保存，即时生效。');
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : String(reason));
    } finally { setBusy(false); onBusyChange(false); }
  };
  const toggleChannel = (channel: NotificationChannel, checked: boolean) => {
    changed();
    setTask(previous => ({ ...previous, channels: checked
      ? [...previous.channels, channel] : previous.channels.filter(value => value !== channel) }));
  };
  const unavailable = loading || busy || !settings;
  const noChannels = task.enabled && task.channels.length === 0;

  return <form className="notification-settings-form project-aow-dialog-form" onSubmit={event => {
    event.preventDefault();
    if (section === 'im') void save({ section: 'im', providers: [{ provider: 'feishu', app_id: appId.trim(), ...(secret.trim() ? { app_secret: secret.trim() } : {}) }] });
    else if (!noChannels) void save({ section: 'notifications', agent_task_completed: task, public_base_url: publicBaseUrl.trim() });
  }}>
    <div className="project-aow-dialog-body">
      <div className="project-aow-settings-heading"><div>
        <h2>{section === 'im' ? 'IM' : '通知'}</h2>
        <p>{section === 'im' ? '配置飞书应用机器人，消息发送给应用所有者。' : '选择 Agent 任务完成后的通知方式。'}</p>
      </div></div>
      {loading && <p role="status">加载配置中…</p>}
      {section === 'im' ? <>
        <h3>飞书 Bot {feishu && <small className="notification-configured">已配置</small>}</h3>
        <label className="project-aow-dialog-field"><span>App ID</span><input aria-label="飞书 App ID" value={appId} disabled={unavailable} spellCheck={false} autoComplete="off" onChange={event => { setAppId(event.target.value); changed(); }} placeholder="cli_…" required /></label>
        <label className="project-aow-dialog-field"><span>App Secret</span><input aria-label="飞书 App Secret" type="password" value={secret} disabled={unavailable} autoComplete="new-password" onChange={event => { setSecret(event.target.value); changed(); }} placeholder={feishu?.app_id === appId.trim() ? '已保存，留空保留现有密钥' : '填写应用密钥'} required={!feishu || feishu.app_id !== appId.trim()} /></label>
        <p className="project-aow-form-intro">使用企业自建应用，在飞书开发者后台开启机器人能力并发布。应用所有者需在可用范围内。</p>
        <p className="project-aow-form-intro">需要开通“管理应用自身资源”和“以应用的身份发消息”权限。保存后，可在“通知”中选择飞书推送。</p>
      </> : <>
        <label className="project-aow-dialog-field"><span>AOW 访问地址</span><input type="url" aria-label="AOW 访问地址" value={publicBaseUrl} disabled={unavailable} spellCheck={false} placeholder="https://aow.example.com" onChange={event => { setPublicBaseUrl(event.target.value); changed(); }} /></label>
        <button type="button" className="project-aow-dialog-button" disabled={unavailable} onClick={() => { setPublicBaseUrl(appBaseUrl()); changed(); }}>使用当前访问地址</button>
        <p className="project-aow-form-intro">用于飞书通知中的 Tab 链接，请填写接收设备可访问的部署入口地址，包含端口和子目录（如有）。留空时飞书只显示 Tab 名称。</p>
        <label className="project-aow-dialog-checkbox notification-checkbox notification-master"><input type="checkbox" checked={task.enabled} disabled={unavailable} onChange={event => {
          changed(); setTask(previous => ({ ...previous, enabled: event.target.checked,
            channels: event.target.checked && !previous.channels.length ? ['page'] : previous.channels }));
        }} /><span>Agent 任务完成</span></label>
        {task.enabled && <fieldset disabled={unavailable} className="notification-channels">
          <legend>通知方式（至少选择一项）</legend>
          <label className="project-aow-dialog-checkbox notification-checkbox"><input type="checkbox" checked={task.channels.includes('page')} onChange={event => toggleChannel('page', event.target.checked)} /><span>页面提示</span></label>
          {feishu && <label className="project-aow-dialog-checkbox notification-checkbox"><input type="checkbox" checked={task.channels.includes('feishu')} onChange={event => toggleChannel('feishu', event.target.checked)} /><span>飞书推送</span></label>}
          {!feishu && <p className="project-aow-form-intro">配置 IM 中的飞书 Bot 后，可选择飞书推送。</p>}
          {noChannels && <p role="alert" className="project-aow-error">至少选择一种通知方式。</p>}
        </fieldset>}
        <p className="project-aow-form-intro">通知包含项目、Tab 名称和触发的 Session ID。飞书推送在网页关闭后仍可发送。</p>
      </>}
      {saved && <p role="status">{saved}</p>}
      {error && <div role="alert" className="project-aow-error">{error}</div>}
    </div>
    <footer className="project-aow-dialog-footer">
      {section === 'im' && feishu && <button type="button" className="project-aow-dialog-button" disabled={unavailable} onClick={() => void save({ section: 'im', providers: [] })}>移除飞书配置</button>}
      <button type="submit" className="project-aow-dialog-button primary" disabled={unavailable || (section === 'notifications' ? noChannels : !appId.trim())}>{busy ? '保存中…' : '保存'}</button>
    </footer>
  </form>;
}

