            context.forceClaim = false;
            clearWaitingRetry(context);
            context.waitingRetryAttempt = 0;
            context.mutationsRevoked = true;
            attempt = 0;
            revokeInput(context.socket);
            setConnection('connecting');
            setConnectionMessage(undefined);
            return;
          }
          if (context.controlState === 'claimed') {
            if (context.legacyMode) {
              context.legacyMode = false;
              return;
            }
            failProtocol(context, '服务器重复授予了终端控制权', 'duplicate terminal control claim');
            return;
          }
          context.controlState = 'claimed';
          context.forceClaim = false;
          clearWaitingRetry(context);
          context.waitingRetryAttempt = 0;
          context.mutationsRevoked = false;
          attempt = 0;
          setConnection('connecting');
          setConnectionMessage(undefined);
          return;
        }
        if (control?.type === 'stream') {
          if (context.controlState === 'pending') {
            // A v1 terminald sends Stream immediately and reports our Claim as
            // invalid_control. Treat that ordering as an implicitly claimed
            // legacy connection so rolling upgrades keep rendering output.
            context.legacyMode = true;
            context.controlState = 'claimed';
            context.forceClaim = false;
            context.mutationsRevoked = false;
          } else if (context.controlState !== 'claimed' && context.controlState !== 'observing') {
            failProtocol(context, '服务器在授予控制权前发送了终端流', 'terminal stream before control claim');
            return;
          }
          if (context.sawStream) {
            failProtocol(context, '服务器重复发送了终端流信息', 'duplicate terminal stream handshake');
            return;
          }
          if (control.epoch === undefined || control.offset === undefined || control.reset === undefined || control.replay_bytes === undefined) {
            failProtocol(context, '服务器返回了无效的终端流信息', 'invalid terminal stream handshake');
            return;
          }
          const restoreValidation = terminalRestore(control as ControlMessage & { reset: boolean });
          if (!restoreValidation.ok) {
            failProtocol(context, restoreValidation.message, restoreValidation.closeReason);
            return;
          }
          if (context.snapshotRecoveryFallback) {
            const fallback = context.snapshotRecoveryFallback;
            const hasVtSnapshot = control.reset
              && restoreValidation.restore?.cols !== undefined
              && restoreValidation.restore.rows !== undefined;
            if (!hasVtSnapshot || control.replay_bytes > MAX_SNAPSHOT_RECOVERY_REPLAY_BYTES) {
              // A fresh attach without an actual VT snapshot would fall back
              // to replaying up to 8 MiB. Preserve the last frame xterm really
              // rendered and resume raw bytes from there instead.
              context.snapshotRecoveryFallback = undefined;
              context.discardSubsequentMessages = true;
              context.mutationsRevoked = true;
              revokeInput(context.socket);
              streamStateRef.current = {
                identity: paneIdentity,
                initialized: true,
                epoch: fallback.epoch,
                nextOffset: fallback.after,
              };
              setRestorePending(false);
              setConnection('disconnected');
              setConnectionMessage('终端快照尚未就绪，正在从已渲染位置续传');
              context.socket.close(1000, 'terminal snapshot recovery unavailable');
              return;
            }
            context.snapshotRecoveryFallback = undefined;
          }
          const previousStream = streamStateRef.current;
          const streamPositionMismatch = !control.reset
            && (previousStream.identity !== paneIdentity
              || !previousStream.initialized
              || control.epoch !== previousStream.epoch
              || control.offset !== previousStream.nextOffset);
          if (streamPositionMismatch) {
            context.mutationsRevoked = true;
            revokeInput(context.socket);
            streamStateRef.current = { identity: paneIdentity, initialized: false, epoch: '', nextOffset: 0 };
            setRestorePending(false);
            setConnection('disconnected');
            setConnectionMessage('终端续传位置不连续，正在重新同步');
            context.discardSubsequentMessages = true;
            context.socket.close(1000, 'terminal stream offset mismatch');
            return;
          }
          context.sawStream = true;
          context.replayBytesRemaining = control.replay_bytes;
          context.replayDone = control.replay_bytes === 0;
          const diagnostics = context.restoreDiagnostics;
          if (diagnostics) {
            const handshakeAt = performance.now();
            const hasVtSnapshot = control.reset
              && restoreValidation.restore?.cols !== undefined
              && restoreValidation.restore.rows !== undefined;
            diagnostics.handshakeMs = handshakeAt - (diagnostics.openedAt ?? diagnostics.startedAt);
            diagnostics.mode = control.reset
              ? (hasVtSnapshot ? 'vt_snapshot' : 'raw_replay')
              : 'resume';
            diagnostics.snapshotUsed = hasVtSnapshot;
            diagnostics.snapshotBytes = hasVtSnapshot && restoreValidation.restore
              ? utf8ByteLength(restoreValidation.restore.data)
              : 0;
            diagnostics.replayBytes = control.replay_bytes;
          }
          streamStateRef.current = { identity: paneIdentity, initialized: true, epoch: control.epoch, nextOffset: control.offset };
          if (control.reset) {
            setRestorePending(true);
            renderedStatusRef.current = undefined;
            await queueTerminalOperation(context, async (terminal) => {
              terminal.reset();
              // The serialized VT stream was produced at these exact
              // dimensions. Parse it at the same geometry so wrapped lines,
              // cursor positions and alternate-screen cells remain stable.
              // Input is still revoked here, so this local resize cannot be
              // reflected back to the PTY before replay completes.
              if (restoreValidation.restore?.cols !== undefined && restoreValidation.restore.rows !== undefined) {
                terminal.resize(restoreValidation.restore.cols, restoreValidation.restore.rows);
              }
              if (restoreValidation.restore !== undefined) {
                const snapshotWriteStartedAt = context.restoreDiagnostics ? performance.now() : 0;
                await terminalWrite(terminal, restoreValidation.restore.data);
                if (context.restoreDiagnostics) {
                  context.restoreDiagnostics.snapshotWriteMs += performance.now() - snapshotWriteStartedAt;
                }
              }
            });
          }
          if (context.replayDone) {
            if (context.controlState === 'claimed') await markInputReady(context);
            else await markObserverReady(context);
          }
          return;
        }
        if (control?.type === 'status' && control.status) {
          if (context.controlState !== 'claimed' && context.controlState !== 'observing') {
            failProtocol(context, '服务器在授予控制权前发送了终端状态', 'terminal status before control claim');
            return;
          }
          if (control.status === 'running') {
            if (context.sawStream && context.replayDone) {
              if (context.controlState === 'claimed') await markInputReady(context);
              else await markObserverReady(context);
            }
          } else {
            await renderStatus(context, control.status, control.exit_code);
          }
          return;
        }
        if (control?.type === 'exit' || control?.type === 'exited') {
          if (context.controlState !== 'claimed' && context.controlState !== 'observing') {
            failProtocol(context, '服务器在授予控制权前发送了终端状态', 'terminal exit before control claim');
            return;
          }
          await renderStatus(context, 'exited', control.exit_code);
          return;
        }
        if (control?.type === 'error') {
          if (context.legacyMode && control.code === 'invalid_control') {
            return;
          }
          if (control.code === 'attachment_superseded') {
            reattachAsObserver(context);
          } else {
            setRestorePending(false);
            setConnectionMessage(control.message || '终端连接发生错误');
            if (control.code === 'output_lagged' || control.code === 'output_gap') {
              context.mutationsRevoked = true;
              revokeInput(context.socket);
              setConnection('disconnected');
              context.socket.close(1000, 'terminal output lagged');
            }
          }
          return;
        }
        if (!control) {
          failProtocol(context, '服务器返回了无法识别的终端消息', 'unknown terminal text message');
        }
        return;
      }

      const buffer = data instanceof Blob ? await data.arrayBuffer() : data;
      if (!contextIsActive(context) || context.discardSubsequentMessages) return;
      const bytes = buffer instanceof Uint8Array ? buffer : new Uint8Array(buffer);
      if ((context.controlState !== 'claimed' && context.controlState !== 'observing') || !context.sawStream) {
        failProtocol(context, '服务器在终端流就绪前发送了输出', 'terminal output before stream');
        return;
      }
      if (context.sawStream && !context.replayDone
        && (context.replayBytesRemaining === undefined || bytes.byteLength > context.replayBytesRemaining)) {
        context.discardSubsequentMessages = true;
        context.mutationsRevoked = true;
        revokeInput(context.socket);
        streamStateRef.current = { identity: paneIdentity, initialized: false, epoch: '', nextOffset: 0 };
        setRestorePending(false);
        setConnection('disconnected');
        setConnectionMessage('服务器返回了无效的终端回放长度，正在重新同步');
        context.socket.close(1000, 'terminal replay length mismatch');
        return;
      }
      const replayChunk = !context.replayDone;
      const written = await queueTerminalOperation(context, async (terminal) => {
        const writeStartedAt = replayChunk && context.restoreDiagnostics ? performance.now() : 0;
        await terminalWrite(terminal, bytes);
        if (replayChunk && context.restoreDiagnostics) {
          context.restoreDiagnostics.replayWriteMs += performance.now() - writeStartedAt;
        }
      });
      if (!written) return;
      if (context.sawStream) {
        const stream = streamStateRef.current;
        if (stream.identity === paneIdentity && stream.initialized) {
          const nextOffset = stream.nextOffset + bytes.byteLength;
          if (Number.isSafeInteger(nextOffset)) stream.nextOffset = nextOffset;
          else stream.initialized = false;
        }
        if (!context.replayDone && context.replayBytesRemaining !== undefined) {
          context.replayBytesRemaining -= bytes.byteLength;
          if (context.replayBytesRemaining === 0) {
            context.replayDone = true;
            if (context.controlState === 'claimed') await markInputReady(context);
            else await markObserverReady(context);
          }
        }
      }
    };

    const binaryByteLength = (data: unknown) => (
      data instanceof ArrayBuffer || data instanceof Uint8Array
        ? data.byteLength
        : data instanceof Blob ? data.size : 0
    );

    const releaseQueuedBinaryBytes = (context: SocketContext, bytes: number) => {
      context.queuedBinaryBytes = Math.max(0, context.queuedBinaryBytes - bytes);
      const globallyQueued = Math.min(bytes, context.globalQueuedBinaryBytes);
      context.globalQueuedBinaryBytes -= globallyQueued;
      queuedTerminalBinaryBytes = Math.max(0, queuedTerminalBinaryBytes - globallyQueued);
    };

    const clearPendingMessages = (context: SocketContext) => {
      let binaryBytes = 0;
      for (const message of context.pendingMessages) binaryBytes += message.binaryBytes;
      context.pendingMessages.length = 0;
      releaseQueuedBinaryBytes(context, binaryBytes);
    };

    const closeForBackpressure = (context: SocketContext) => {
      if (!contextIsActive(context) || context.backpressureClosing) return true;
      const liveBacklogExceeded = context.replayDone
        && (context.queuedBinaryBytes > MAX_LIVE_QUEUED_BINARY_BYTES
          || context.pendingMessages.length > MAX_LIVE_PENDING_MESSAGES);
      const totalBacklogExceeded = context.queuedBinaryBytes > MAX_REPLAY_QUEUED_BINARY_BYTES
        || queuedTerminalBinaryBytes > MAX_REPLAY_QUEUED_BINARY_BYTES;
      if (!liveBacklogExceeded && !totalBacklogExceeded) return false;

      // Stop rendering stale frames. After the one xterm write already in
      // flight completes, reconnect without a raw resume cursor so terminald
      // can restore the most recent VT snapshot plus its short raw suffix.
      context.backpressureClosing = true;
      context.requestSnapshotRecovery = true;
      context.discardSubsequentMessages = true;
      context.mutationsRevoked = true;
      revokeInput(context.socket);
      clearPendingMessages(context);
      setConnection('disconnected');
      setConnectionMessage('终端输出较快，正在同步最新画面');
      context.socket.close(1000, 'terminal output backpressure');
      return true;
    };

    const nextPendingMessage = (context: SocketContext) => {
      const first = context.pendingMessages.shift();
      if (!first || first.binaryBytes === 0 || first.data instanceof Blob) return first;

      const firstBinary = first.data as ArrayBuffer | Uint8Array;
      const chunks = [firstBinary instanceof Uint8Array ? firstBinary : new Uint8Array(firstBinary)];
      let binaryBytes = first.binaryBytes;
      // `replay_bytes` is a protocol barrier even though the next live frame
      // is also binary. Never merge across it: replay completion controls when
      // input and resize become legal again.
      const batchLimit = !context.replayDone && context.replayBytesRemaining !== undefined
        ? Math.min(MAX_XTERM_WRITE_BATCH_BYTES, context.replayBytesRemaining)
        : MAX_XTERM_WRITE_BATCH_BYTES;
      while (context.pendingMessages.length > 0) {
        const next = context.pendingMessages[0];
        if (next.binaryBytes === 0 || next.data instanceof Blob
          || binaryBytes + next.binaryBytes > batchLimit) break;
        context.pendingMessages.shift();
        chunks.push(next.data instanceof Uint8Array ? next.data : new Uint8Array(next.data as ArrayBuffer));
        binaryBytes += next.binaryBytes;
      }
      if (chunks.length === 1) return first;
      const combined = new Uint8Array(binaryBytes);
      let offset = 0;
      for (const chunk of chunks) {
        combined.set(chunk, offset);
        offset += chunk.byteLength;
      }
      return { data: combined, binaryBytes };
    };

    const drainPendingMessages = (context: SocketContext) => {
      if (context.drainingMessages) return;
      context.drainingMessages = true;
      context.messageQueue = (async () => {
        try {
          while (contextIsActive(context) && !context.discardSubsequentMessages) {
            const message = nextPendingMessage(context);
            if (!message) break;
            try {
              await processMessage(context, message.data);
            } finally {
              releaseQueuedBinaryBytes(context, message.binaryBytes);
            }
            if (closeForBackpressure(context)) break;
          }
        } finally {
          if (context.discardSubsequentMessages) clearPendingMessages(context);
          context.drainingMessages = false;
        }
      })().catch(() => {
        if (contextIsActive(context) && !context.backpressureClosing) {
          context.discardSubsequentMessages = true;
          context.mutationsRevoked = true;
          revokeInput(context.socket);
          clearPendingMessages(context);
          setConnection('disconnected');
          setConnectionMessage('终端输出处理失败，正在续传');
          context.socket.close(1000, 'terminal output processing failed');
        }
      });
    };

    const reconnectAfterClose = async (context: SocketContext, epoch: number) => {
      await context.closed;
      await context.messageQueue;
      if (!contextIsActive(context) || epoch !== restartEpoch) return;
      if (!context.allowReconnect || paneStatusRef.current !== 'running') return;
      let snapshotRecoveryFallback: { epoch: string; after: number } | undefined;
      if (context.requestSnapshotRecovery && Date.now() >= nextSnapshotRecoveryAt) {
        const stream = streamStateRef.current;
        if (stream.identity === paneIdentity && stream.initialized) {
          snapshotRecoveryFallback = { epoch: stream.epoch, after: stream.nextOffset };
          nextSnapshotRecoveryAt = Date.now() + SNAPSHOT_RECOVERY_COOLDOWN_MS;
        }
      }
      context.mutationsRevoked = true;
      revokeInput(context.socket);
      setConnection('disconnected');
      attempt += 1;
      retryTimer = window.setTimeout(() => {
        retryTimer = undefined;
        if (contextIsActive(context) && epoch === restartEpoch) {
          connect(context.forceClaim, snapshotRecoveryFallback);
        }
      }, Math.min(8000, 500 * 2 ** Math.min(attempt - 1, 4)));
    };

    function connect(
      forceClaim = false,
      snapshotRecoveryFallback?: { epoch: string; after: number },
    ) {
      if (disposed) return;
      setConnection(attempt === 0 ? 'connecting' : 'disconnected');
      const stream = streamStateRef.current;
      const resume = snapshotRecoveryFallback === undefined
        && stream.identity === paneIdentity && stream.initialized
        ? { epoch: stream.epoch, after: stream.nextOffset }
        : undefined;
      const restoreDiagnostics: TerminalRestoreDiagnostics | undefined = terminalRestoreDebugEnabled()
        ? {
          startedAt: performance.now(),
          mode: resume ? 'resume' : 'raw_replay',
          snapshotUsed: false,
          snapshotBytes: 0,
          snapshotWriteMs: 0,
          replayBytes: 0,
          replayWriteMs: 0,
          reported: false,
        }
        : undefined;
      if (resume === undefined) setRestorePending(true);
      const currentSocket = new WebSocket(terminalApi.webSocketUrl(tabId, pane.id, resume));
      currentSocket.binaryType = 'arraybuffer';
      generation += 1;
      let resolveClosed = () => {};
      const closed = new Promise<void>((resolve) => { resolveClosed = resolve; });
      const context: SocketContext = {
        socket: currentSocket,
        generation,
        messageQueue: Promise.resolve(),
        pendingMessages: [],
        drainingMessages: false,
        closed,
        resolveClosed,
        allowReconnect: true,
        observerReattachStarted: false,
        sawStream: false,
        legacyMode: false,
        replayBytesRemaining: undefined,
        replayDone: false,
        controlState: 'pending',
        forceClaim,
        mutationsRevoked: false,
        queuedBinaryBytes: 0,
        globalQueuedBinaryBytes: 0,
        backpressureClosing: false,
        requestSnapshotRecovery: false,
        snapshotRecoveryFallback,
        discardSubsequentMessages: false,
        waitingRetryTimer: undefined,
        waitingRetryAttempt: 0,
        restoreDiagnostics,
      };
      activeContext = context;
      socketRef.current = currentSocket;
      revokeInput();

      currentSocket.onopen = () => {
        if (!contextIsActive(context)) return;
        if (context.restoreDiagnostics) {
          context.restoreDiagnostics.openedAt = performance.now();
          context.restoreDiagnostics.websocketOpenMs = context.restoreDiagnostics.openedAt
            - context.restoreDiagnostics.startedAt;
        }
        setConnection('connecting');
        currentSocket.send(terminalApi.claimMessage(forceClaim));
      };
      currentSocket.onmessage = (event) => {
        if (!contextIsActive(context) || context.discardSubsequentMessages || context.backpressureClosing) return;
        if (typeof event.data === 'string') {
          const immediate = controlMessage(event.data);
          if (immediate?.type === 'error' && immediate.code === 'attachment_superseded') {
            // This must happen before queuing output behind a slow xterm write.
            reattachAsObserver(context);
            return;
          }
          if (immediate?.type === 'control' && (immediate.state === 'waiting' || immediate.state === 'observing')) {
            // Revoke synchronously rather than waiting behind xterm writes.
            context.mutationsRevoked = true;
            revokeInput(context.socket);
            if (immediate.type === 'control' && immediate.state === 'waiting') {
              context.controlState = 'waiting';
              context.forceClaim = false;
              setRestorePending(false);
              setConnection('waiting');
              setConnectionMessage(undefined);
              scheduleWaitingRetry(context);
            } else if (immediate.type === 'control') {
              context.controlState = 'observing';
              context.forceClaim = false;
              clearWaitingRetry(context);
              setConnection('connecting');
              setConnectionMessage(undefined);
            }
          }
        }
        const queuedBytes = binaryByteLength(event.data);
        context.queuedBinaryBytes += queuedBytes;
        context.globalQueuedBinaryBytes += queuedBytes;
        queuedTerminalBinaryBytes += queuedBytes;
        context.pendingMessages.push({
          data: event.data as string | ArrayBuffer | Blob,
          binaryBytes: queuedBytes,
        });
        if (!closeForBackpressure(context)) drainPendingMessages(context);
      };
      currentSocket.onerror = () => currentSocket.close();
      currentSocket.onclose = () => {
        clearWaitingRetry(context);
        context.mutationsRevoked = true;
        revokeInput(currentSocket);
        context.resolveClosed();
        if (currentSocket === socketRef.current) socketRef.current = undefined;
        if (currentSocket === inputReadySocketRef.current) inputReadySocketRef.current = undefined;
        void reconnectAfterClose(context, restartEpoch);
      };
    }

    manualReconnectRef.current = (force = false) => {
      if (force && agentPhaseRef.current && agentPhaseRef.current !== 'ready') return;
      restartEpoch += 1;
      if (retryTimer !== undefined) {
        window.clearTimeout(retryTimer);
        retryTimer = undefined;
      }
      setConnection('connecting');
      setConnectionMessage(undefined);
      const context = activeContext;
      if (!context) {
        connect(force);
        return;
      }
      context.allowReconnect = false;
      clearWaitingRetry(context);
      context.discardSubsequentMessages = true;
      context.mutationsRevoked = true;
      revokeInput(context.socket);
      clearPendingMessages(context);
      streamStateRef.current = { identity: paneIdentity, initialized: false, epoch: '', nextOffset: 0 };
      if (context.socket.readyState === WebSocket.CONNECTING || context.socket.readyState === WebSocket.OPEN) {
        context.socket.close(1000, 'manual terminal takeover');
      } else if (context.socket.readyState === WebSocket.CLOSED) {
        context.resolveClosed();
      }
      // A browser can keep a network-lost WebSocket OPEN or CLOSING for a long
      // time. Do not make an explicit user action wait for that stale socket's
      // close event. The terminal operation queue still keeps any write that
      // already started ahead of the new connection's reset/replay.
      connect(force);
    };

    connect(forceOnAttach);
    return () => {
      disposed = true;
      restartEpoch += 1;
      if (retryTimer !== undefined) window.clearTimeout(retryTimer);
      manualReconnectRef.current = () => {};
      mutationGenerationRef.current += 1;
      inputReadySocketRef.current = undefined;
      const context = activeContext;
      if (context) clearWaitingRetry(context);
      if (context?.globalQueuedBinaryBytes) {
        queuedTerminalBinaryBytes = Math.max(0, queuedTerminalBinaryBytes - context.globalQueuedBinaryBytes);
        context.globalQueuedBinaryBytes = 0;
      }
      if (context) context.pendingMessages.length = 0;
      if (context?.socket === socketRef.current) socketRef.current = undefined;
      context?.socket.close(1000, 'terminal pane detached');
    };
  }, [pane.id, paneIdentity, tabId, attachEnabled]);

  return (
    <div
      ref={shellRef}
      className={`terminal-emulator-shell${pane.agent_terminal && sizing === 'saved' && !mobileInput ? ' terminal-cli-observer' : ''}${sizing === 'saved' ? ' terminal-saved-size' : ''}${restorePending ? ' restore-pending' : ''}`}
      data-terminal-sizing={sizing}
      aria-busy={restorePending}
      onPointerDown={onFocus}
    >
      {visible && pendingLink?.identity === paneIdentity ? (
        <ConfirmationDialog
          title="打开链接"
          description="将在新标签页中打开以下链接。"
          items={[{ id: pendingLink.url.href, label: pendingLink.url.host, detail: pendingLink.url.href, icon: <ExternalLink aria-hidden="true" /> }]}
          warning="请确认链接来源可信后再打开。"
          confirmLabel="打开链接"
          onResult={(confirmed) => {
            setPendingLink(null);
            // Open directly from the confirmation click to retain user activation.
            if (confirmed) window.open(pendingLink.url.href, '_blank', 'noopener,noreferrer');
          }}
        />
      ) : null}
      <div ref={hostRef} className="terminal-emulator" />
      {restorePending ? (
        <div className="terminal-restore-status" role="status" aria-live="polite">
          <span aria-hidden="true" />
          正在恢复终端…
        </div>
      ) : null}
      {clipboardImageState ? (
        <div className={`terminal-clipboard-image-status ${clipboardImageState.status}`} role="status" aria-live="polite">
          <span aria-hidden="true" />
          {clipboardImageState.message}
        </div>
      ) : null}
      {clipboardCopyState && active && visible ? (
        <div className={`terminal-clipboard-copy-status ${clipboardCopyState.status}`} role="status" aria-live="polite">
          <ClipboardCopy aria-hidden="true" />
          <span>{clipboardCopyState.message}</span>
          {clipboardCopyState.text ? (
            <button type="button" onClick={(event) => { event.stopPropagation(); void completePendingClipboardCopy(); }}>复制</button>
          ) : null}
          <button
            type="button"
            className="dismiss"
            aria-label="关闭复制提示"
            title="关闭"
            onClick={(event) => { event.stopPropagation(); clearClipboardCopyTimer(); setClipboardCopyState(null); }}
          >
            <X />
          </button>
        </div>
      ) : null}
      <div className={`terminal-connection ${connection}${connectionMessage ? ' has-message' : ''}`} role="status" aria-live="polite">
        <span title={connectionMessage || pane.agent_terminal?.error || undefined}>{terminalPaneStatusMessage(pane, connection, connectionMessage)}</span>
        {connection === 'observing' || connection === 'waiting' ? (
          <button
            type="button"
            className="terminal-takeover-action"
            disabled={Boolean(pane.agent_terminal && pane.agent_terminal.phase !== 'ready')}
            onClick={(event) => { event.stopPropagation(); manualReconnectRef.current(true); }}
          >
            接管
          </button>
        ) : connection === 'disconnected' ? (
          <button
            title="立即重连"
            aria-label="立即重连"
            onClick={(event) => { event.stopPropagation(); manualReconnectRef.current(false); }}
          >
            <RefreshCw />
          </button>
        ) : null}
      </div>
    </div>
  );
}

import { useCallback, useId, useRef, useState } from 'react';
import { ChevronRight, Eye, EyeOff, Glasses, MoreHorizontal, RefreshCw, ShieldCheck, SquareTerminal, Unplug, UserRound } from 'lucide-react';
import type { TerminalTab } from './types';
import type { AowWorktree } from '../../aow/types';
import { isCliTerminal, terminalTabPresentation } from './terminalPresentation';
import { terminalControlLabels, terminalDisplayLabels, terminalLifecycleLabels } from './terminalState';
import { useTerminalStates } from './terminalViewState';
import { TerminalLifecycleDot } from './TerminalLifecycleDot';
import { AgentIcon } from '../agents/AgentIcon';
import { AowIconButton } from '../../components/AowIconButton';
import { AowPanel, AowPanelStack } from '../../components/AowPanel';
import { AowListRow } from '../../components/AowListRow';
import { useConfirmation } from '../../components/ConfirmationDialog';
import { TerminalContextMenu } from './TerminalContextMenu';
import { TerminalScopeMenu, type TerminalSort } from './TerminalScopeMenu';
import './terminal-panel.css';

const terminalGroups = [
  { id: 'user', cli: false, title: 'User Terminals', icon: UserRound, tooltip: '用户创建' },
  { id: 'cli', cli: true, title: 'CLI Terminals', icon: SquareTerminal, tooltip: <><code>aow-cli agent</code> 创建</> },
] as const;

type TerminalGroup = typeof terminalGroups[number]['id'];
const terminalDisplayIcons = { shown: Eye, hidden: EyeOff };
const terminalControlIcons = { observing: Glasses, controlled: ShieldCheck, disconnected: Unplug };

function worktreeName(worktree: AowWorktree) {
  return worktree.detached ? 'detached'
    : worktree.branch || worktree.path.split('/').filter(Boolean).at(-1) || worktree.path;
}

function terminalCreatedAt(tab: TerminalTab) {
  const timestamp = typeof tab.created_at === 'number' ? tab.created_at : Date.parse(tab.created_at ?? '');
  return Number.isFinite(timestamp) ? timestamp : Number.MAX_SAFE_INTEGER;
}

export function TerminalPanel({ tabs, detectedAgents, titles, openedIds, activeId, onOpen, onOpenFloating, onTerminate, onRebuild, onReload,
  worktrees, showAll = { user: false, cli: false }, onShowAllChange,
  sortBy = { user: 'branch', cli: 'branch' }, onSortChange, loading = false, error, menuContainer }: {
  tabs: TerminalTab[];
  detectedAgents: Record<string, string | null>;
  titles: Record<string, string>;
  openedIds: Set<string>;
  activeId?: string;
  onOpen: (tab: TerminalTab) => void;
  onOpenFloating?: (tab: TerminalTab) => void;
  onTerminate: (id: string) => Promise<void>;
  onRebuild: (id: string) => Promise<void>;
  onReload: () => void;
  worktrees?: AowWorktree[];
  showAll?: Record<TerminalGroup, boolean>;
  onShowAllChange?: (group: TerminalGroup, showAll: boolean) => void;
  sortBy?: Record<TerminalGroup, TerminalSort>;
  onSortChange?: (group: TerminalGroup, sortBy: TerminalSort) => void;
  loading?: boolean;
  error?: string;
  menuContainer?: HTMLElement;
}) {
  const panelId = useId();
  const terminalState = useTerminalStates();
  const [collapsedGroups, setCollapsedGroups] = useState<Partial<Record<TerminalGroup, boolean>>>({});
  const [collapsedWorktrees, setCollapsedWorktrees] = useState<Record<string, boolean>>({});
  const [scopeMenu, setScopeMenu] = useState<{ anchor: HTMLButtonElement; group: TerminalGroup }>();
  const dismissScopeMenu = useCallback(() => setScopeMenu(undefined), []);
  const [contextMenu, setContextMenu] = useState<{ tabId: string; x: number; y: number }>();
  const dismissMenu = useCallback(() => setContextMenu(undefined), []);
  const menuTab = contextMenu ? tabs.find(tab => tab.id === contextMenu.tabId) : undefined;
  const rebuildingIds = useRef(new Set<string>());
  const [rebuilding, setRebuilding] = useState<Set<string>>(new Set());
  const [rebuildError, setRebuildError] = useState('');
  const rebuild = async (id: string) => {
    if (rebuildingIds.current.has(id)) return;
    rebuildingIds.current.add(id);
    setRebuilding(new Set(rebuildingIds.current));
    setRebuildError('');
    try { await onRebuild(id); }
    catch (reason) { setRebuildError(reason instanceof Error ? reason.message : String(reason)); }
    finally {
      rebuildingIds.current.delete(id);
      setRebuilding(new Set(rebuildingIds.current));
    }
  };
  const { confirm, confirmationDialog } = useConfirmation();
  const terminate = async (tab: TerminalTab) => {
    const title = terminalTabPresentation(tab, detectedAgents, titles).title;
    if (await confirm({ title: '销毁终端？', description: `销毁 ${title} 及其全部窗格。`,
      warning: '此操作会结束正在运行的进程和任务，worktree 和已保存的会话记录会保留。', confirmLabel: '销毁', danger: true })) {
      await onTerminate(tab.id);
    }
  };
  const renderTab = (tab: TerminalTab) => {
    const presentation = terminalTabPresentation(tab, detectedAgents, titles);
    const pane = tab.panes.find(pane => pane.agent_terminal) ?? tab.panes[0];
    const state = terminalState(tab, openedIds.has(tab.id));
    const DisplayIcon = terminalDisplayIcons[state.display];
    const ControlIcon = terminalControlIcons[state.control];
    const displayLabel = terminalDisplayLabels[state.display];
    const controlLabel = terminalControlLabels[state.control];
    return <AowListRow className={`terminal-panel-row${tab.id === activeId ? ' active' : ''}`}
      openClassName="terminal-panel-open" key={tab.id}
      title={presentation.title} tooltip={presentation.title}
      icon={<AgentIcon agentId={presentation.agentId ?? pane?.agent_id} />} onOpen={() => onOpen(tab)}
      menuLabel="终端操作" menuExpanded={contextMenu?.tabId === tab.id}
      onMenu={(x, y) => { dismissScopeMenu(); setContextMenu({ tabId: tab.id, x, y }); }}>
      <small className="terminal-panel-status">
        <TerminalLifecycleDot className="terminal-panel-status-dot" state={state.lifecycle} />
        <span className="terminal-panel-status-label">{terminalLifecycleLabels[state.lifecycle]}</span>
        <span className="terminal-panel-status-separator" aria-hidden="true">·</span>
        <DisplayIcon className={state.display === 'shown' ? 'terminal-panel-state-active' : undefined}
          role="img" aria-label={displayLabel}><title>{displayLabel}</title></DisplayIcon>
        <span className="terminal-panel-status-separator" aria-hidden="true">·</span>
        <ControlIcon className={state.control === 'controlled' ? 'terminal-panel-state-active' : undefined}
          role="img" aria-label={controlLabel}><title>{controlLabel}</title></ControlIcon>
      </small>
    </AowListRow>;
  };
  return <section className="terminal-panel">
    {rebuildError ? <p className="terminal-panel-error" role="alert">{rebuildError}</p> : null}
    <AowPanelStack className="terminal-panel-groups">
      {terminalGroups.map(({ id, cli, title, icon: Icon, tooltip }) => {
        const items = tabs.filter(tab => isCliTerminal(tab) === cli);
        const grouped = showAll[id] && !!worktrees;
        const groupLoading = grouped && loading;
        const collapsed = collapsedGroups[id] ?? (items.length === 0 && !groupLoading && !(grouped && error));
        const bodyId = `${panelId}-${id}`;
        const branches = grouped ? [...worktrees]
          .sort((left, right) => Number(right.is_main) - Number(left.is_main)
            || worktreeName(left).localeCompare(worktreeName(right)))
          .map(worktree => ({ key: `worktree:${worktree.path}`, worktree, members: items.filter(tab => tab.workspace_root === worktree.path) }))
          .filter(group => group.members.length) : [];
        const sections = sortBy[id] === 'createdAt'
          ? branches.flatMap(group => group.members.map(tab => ({ ...group, key: `terminal:${tab.id}`, members: [tab] })))
            .sort((left, right) => terminalCreatedAt(left.members[0]) - terminalCreatedAt(right.members[0]))
          : branches;
        return <AowPanel key={id} className="terminal-panel-group" bodyClassName="terminal-panel-body" title={title} tooltip={tooltip} icon={<Icon />} collapsed={collapsed} controlsId={bodyId}
            onCollapsedChange={next => setCollapsedGroups(groups => ({ ...groups, [id]: next }))}
            details={grouped ? <span className="terminal-panel-count">{items.length}</span> : undefined}
            actions={<>
              <AowIconButton title="刷新终端列表" aria-label={`刷新 ${title}`} onClick={onReload}><RefreshCw /></AowIconButton>
              {worktrees && onShowAllChange ? <AowIconButton title="终端显示范围" aria-label={`${title} 显示范围`}
                aria-haspopup="menu" aria-expanded={scopeMenu?.group === id}
                className={grouped ? 'terminal-scope-active' : undefined}
                onClick={event => {
                  dismissMenu();
                  const anchor = event.currentTarget;
                  setScopeMenu(current => current?.group === id ? undefined : { anchor, group: id });
                }}><MoreHorizontal /></AowIconButton> : null}
            </>}>
            {grouped && error ? <p className="terminal-panel-error" role="alert">{error}</p> : null}
            {groupLoading ? <p className="terminal-panel-empty" role="status">正在加载所有终端…</p> : null}
            {!items.length && !groupLoading ? <p className="terminal-panel-empty">暂无终端</p> : grouped ? sections
              .map(({ key: sectionKey, worktree, members }, index) => {
                const key = `${id}:${sectionKey}`;
                const collapsed = collapsedWorktrees[key] ?? false;
                const groupId = `${bodyId}-worktree-${index}`;
                const name = worktreeName(worktree);
                return <section className="terminal-worktree-group" key={sectionKey} aria-label={worktree.path}>
                  <button className="terminal-worktree-heading" title={`${worktree.path}${worktree.branch ? `\n${worktree.branch}` : ''}`}
                    aria-expanded={!collapsed} aria-controls={groupId}
                    onClick={() => setCollapsedWorktrees(groups => ({ ...groups, [key]: !groups[key] }))}>
                    <ChevronRight className={collapsed ? undefined : 'expanded'} />
                    <span>{worktree.is_main ? '主仓库 · ' : ''}{name}</span>
                    <small className="terminal-panel-count">{members.length}</small>
                  </button>
                  <div id={groupId} hidden={collapsed}>{members.map(renderTab)}</div>
                </section>;
              }) : items.map(renderTab)}
        </AowPanel>;
      })}
    </AowPanelStack>
    {scopeMenu && worktrees && onShowAllChange ? <TerminalScopeMenu container={menuContainer} anchor={scopeMenu.anchor} checked={showAll[scopeMenu.group]}
      sortBy={sortBy[scopeMenu.group]} onSortChange={value => onSortChange?.(scopeMenu.group, value)}
      onChange={value => onShowAllChange(scopeMenu.group, value)} onClose={dismissScopeMenu} /> : null}
    {contextMenu && menuTab ? <TerminalContextMenu container={menuContainer} x={contextMenu.x} y={contextMenu.y}
      title={terminalTabPresentation(menuTab, detectedAgents, titles).title} onClose={dismissMenu}
      onOpen={() => onOpen(menuTab)} onOpenFloating={onOpenFloating ? () => onOpenFloating(menuTab) : undefined}
      onRebuild={menuTab.panes.length > 0 && menuTab.panes.every(pane => pane.status !== 'running')
        ? () => void rebuild(menuTab.id) : undefined} rebuilding={rebuilding.has(menuTab.id)}
      onDestroy={() => void terminate(menuTab)} /> : null}
    {confirmationDialog}
  </section>;
}

import { useEffect, useLayoutEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { Check } from 'lucide-react';

export type TerminalSort = 'branch' | 'createdAt';
const sortOptions = [{ value: 'branch', label: '按分支名' }, { value: 'createdAt', label: '按创建时间' }] as const;

export function TerminalScopeMenu({ anchor, checked, sortBy, onSortChange, onChange, onClose, container }: {
  container?: HTMLElement;
  anchor: HTMLButtonElement;
  checked: boolean;
  sortBy: TerminalSort;
  onSortChange: (sortBy: TerminalSort) => void;
  onChange: (checked: boolean) => void;
  onClose: () => void;
}) {
  const menu = useRef<HTMLDivElement>(null);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  useLayoutEffect(() => {
    const trigger = anchor.getBoundingClientRect();
    const bounds = menu.current!.getBoundingClientRect();
    setPosition({
      x: Math.max(4, Math.min(trigger.right - bounds.width, window.innerWidth - bounds.width - 4)),
      y: Math.max(4, Math.min(trigger.bottom, window.innerHeight - bounds.height - 4)),
    });
    menu.current?.querySelector('button')?.focus();
  }, [anchor]);
  useEffect(() => {
    const outside = (event: PointerEvent) => {
      if (!menu.current?.contains(event.target as Node) && !anchor.contains(event.target as Node)) onClose();
    };
    const close = () => onClose();
    const key = (event: KeyboardEvent) => {
      if (event.key === 'Escape') { event.preventDefault(); onClose(); anchor.focus(); }
      if (event.key === 'Tab') onClose();
    };
    window.addEventListener('pointerdown', outside);
    window.addEventListener('resize', close);
    window.addEventListener('scroll', close, true);
    window.addEventListener('keydown', key);
    return () => {
      window.removeEventListener('pointerdown', outside);
      window.removeEventListener('resize', close);
      window.removeEventListener('scroll', close, true);
      window.removeEventListener('keydown', key);
    };
  }, [anchor, onClose]);
  return createPortal(<div ref={menu} className="project-aow-context-menu terminal-scope-menu"
    style={{ left: position.x, top: position.y }} role="menu" aria-label="终端显示范围">
    <button role="menuitemcheckbox" aria-checked={checked} onClick={() => {
      onChange(!checked); onClose(); anchor.focus();
    }}><Check style={{ visibility: checked ? 'visible' : 'hidden' }} />显示所有Worktree</button>
    {checked ? <>
      <div className="terminal-scope-menu-separator" role="separator" />
      {sortOptions.map(option => <button key={option.value} role="menuitemradio" aria-checked={sortBy === option.value}
        onClick={() => { onSortChange(option.value); onClose(); anchor.focus(); }}>
        <Check style={{ visibility: sortBy === option.value ? 'visible' : 'hidden' }} />{option.label}
      </button>)}
    </> : null}
  </div>, container ?? document.body);
}

import { useEffect } from 'react';
import { createPortal } from 'react-dom';
import { Columns2, SquareTerminal } from 'lucide-react';
import type { TerminalTabPresentation } from './terminalPresentation';
import { AgentIcon } from '../agents/AgentIcon';

export function TerminalTabIcon({ summary }: { summary?: TerminalTabPresentation }) {
  return summary?.agentId ? <AgentIcon agentId={summary.agentId} />
    : summary && summary.agentCount > 1 ? <Columns2 /> : <SquareTerminal />;
}

export function TerminalTabPreview({ id, summary, left, top, onDismiss }: {
  id: string;
  summary: TerminalTabPresentation;
  left: number;
  top: number;
  onDismiss: () => void;
}) {
  useEffect(() => {
    const escape = (event: KeyboardEvent) => {
      if (event.key !== 'Escape') return;
      event.preventDefault();
      event.stopPropagation();
      onDismiss();
    };
    window.addEventListener('keydown', escape, true);
    window.addEventListener('scroll', onDismiss, true);
    window.addEventListener('resize', onDismiss);
    return () => {
      window.removeEventListener('keydown', escape, true);
      window.removeEventListener('scroll', onDismiss, true);
      window.removeEventListener('resize', onDismiss);
    };
  }, [onDismiss]);

  return createPortal(
    <div id={id} role="tooltip" className="terminal-tab-preview" style={{ left, top }}>
      {summary.panes.map(pane => <div key={pane.id} className="terminal-tab-preview-pane">
        {pane.agentId ? <AgentIcon agentId={pane.agentId} /> : <SquareTerminal />}
        <span>{pane.title}</span>
      </div>)}
    </div>,
    document.body,
  );
}

import { useEffect, useRef, useState, type DragEvent as ReactDragEvent, type PointerEvent as ReactPointerEvent, type ReactNode } from 'react';
import { Columns2, GripVertical, LoaderCircle, Maximize2, Minimize2, Rows2, SquareTerminal, X } from 'lucide-react';
import { terminalApi } from './terminalApi';
import type { TerminalAgentProcess, TerminalLayout, TerminalPane, TerminalPaneStatus, TerminalSplitAxis, TerminalTab } from './types';
import { TerminalInputPane } from './TerminalInputPane';
import { TerminalAgentPane } from './TerminalAgentPane';
import { AgentIcon } from '../agents/AgentIcon';
import { terminalPaneAgent, terminalPaneTitle } from './terminalPresentation';
import { terminalPaneLifecycle } from './terminalState';
import { TerminalLifecycleDot } from './TerminalLifecycleDot';
import { useConfirmation } from '../../components/ConfirmationDialog';

interface Props {
  visible: boolean;
  tab?: TerminalTab;
  loading: boolean;
  detectedAgents: Record<string, string | null>;
  terminalTitles: Record<string, string>;
  agentProcesses?: Record<string, TerminalAgentProcess>;
  onTabChange: (tab: TerminalTab) => void;
  onTabClosed: (tabId: string) => void;
  onPaneStatus: (tabId: string, paneId: string, status: TerminalPaneStatus, exitCode?: number | null) => void;
  onReload: () => void;
}

function message(reason: unknown) {
  return reason instanceof Error ? reason.message : String(reason);
}

function paneIds(layout: TerminalLayout | null): string[] {
  if (!layout) return [];
  if (layout.type === 'pane') return [layout.pane_id];
  return [...paneIds(layout.first), ...paneIds(layout.second)];
}

function replaceRatio(layout: TerminalLayout, path: number[], ratio: number): TerminalLayout {
  if (!path.length) return layout.type === 'split' ? { ...layout, ratio } : layout;
  if (layout.type !== 'split') return layout;
  const [branch, ...rest] = path;
  return branch === 0
    ? { ...layout, first: replaceRatio(layout.first, rest, ratio) }
    : { ...layout, second: replaceRatio(layout.second, rest, ratio) };
}

type PaneDropDirection = 'left' | 'right' | 'top' | 'bottom';

interface PaneDropTarget {
  paneId: string;
  direction: PaneDropDirection;
}

const paneDropLabels: Record<PaneDropDirection, string> = {
  left: '移到左侧',
  right: '移到右侧',
  top: '移到上方',
  bottom: '移到下方',
};

function removePaneFromLayout(layout: TerminalLayout, paneId: string): TerminalLayout | null {
  if (layout.type === 'pane') return layout.pane_id === paneId ? null : layout;
  const first = removePaneFromLayout(layout.first, paneId);
  const second = removePaneFromLayout(layout.second, paneId);
  if (!first) return second;
  if (!second) return first;
  return first === layout.first && second === layout.second ? layout : { ...layout, first, second };
}

function insertPaneAtTarget(
  layout: TerminalLayout,
  sourcePaneId: string,
  targetPaneId: string,
  direction: PaneDropDirection,
): TerminalLayout {
  if (layout.type === 'pane') {
    if (layout.pane_id !== targetPaneId) return layout;
    const source: TerminalLayout = { type: 'pane', pane_id: sourcePaneId };
    const sourceFirst = direction === 'left' || direction === 'top';
    return {
      type: 'split',
      axis: direction === 'left' || direction === 'right' ? 'row' : 'column',
      ratio: 0.5,
      first: sourceFirst ? source : layout,
      second: sourceFirst ? layout : source,
    };
  }
  if (paneIds(layout.first).includes(targetPaneId)) {
    return { ...layout, first: insertPaneAtTarget(layout.first, sourcePaneId, targetPaneId, direction) };
  }
  return { ...layout, second: insertPaneAtTarget(layout.second, sourcePaneId, targetPaneId, direction) };
}

function movePaneInLayout(
  layout: TerminalLayout,
  sourcePaneId: string,
  targetPaneId: string,
  direction: PaneDropDirection,
): TerminalLayout | null {
  if (sourcePaneId === targetPaneId) return null;
  const ids = paneIds(layout);
  if (!ids.includes(sourcePaneId) || !ids.includes(targetPaneId)) return null;
  const remaining = removePaneFromLayout(layout, sourcePaneId);
  return remaining ? insertPaneAtTarget(remaining, sourcePaneId, targetPaneId, direction) : null;
}

function paneDropDirection(event: ReactDragEvent<HTMLElement>): PaneDropDirection {
  const bounds = event.currentTarget.getBoundingClientRect();
  const x = Math.min(1, Math.max(0, (event.clientX - bounds.left) / Math.max(bounds.width, 1)));
  const y = Math.min(1, Math.max(0, (event.clientY - bounds.top) / Math.max(bounds.height, 1)));
  const distances: Array<[PaneDropDirection, number]> = [
    ['left', x],
    ['right', 1 - x],
    ['top', y],
    ['bottom', 1 - y],
  ];
  return distances.reduce((nearest, candidate) => candidate[1] < nearest[1] ? candidate : nearest)[0];
}

function fallbackLayout(tab: TerminalTab): TerminalLayout | null {
  return tab.layout ?? (tab.panes[0] ? { type: 'pane', pane_id: tab.panes[0].id } : null);
}

type TerminalShortcutPlatform = 'macos' | 'windows' | 'linux';

function terminalShortcutPlatform(): TerminalShortcutPlatform {
  if (/Mac|iPhone|iPad|iPod/.test(navigator.userAgent)) return 'macos';
  if (/Windows/.test(navigator.userAgent)) return 'windows';
  return 'linux';
}

function splitShortcutAxis(event: KeyboardEvent, platform: TerminalShortcutPlatform): TerminalSplitAxis | undefined {
  const key = event.key.toLowerCase();
  if (platform === 'macos') {
    if (!event.metaKey || event.ctrlKey || event.altKey || key !== 'd') return undefined;
    return event.shiftKey ? 'column' : 'row';
  }
  if (platform === 'windows') {
    if (!event.altKey || !event.shiftKey || event.ctrlKey || event.metaKey) return undefined;
    if (key === '=' || key === '+') return 'row';
    return key === '-' ? 'column' : undefined;
  }
  if (!event.ctrlKey || !event.shiftKey || event.altKey || event.metaKey) return undefined;
  if (key === 'e') return 'row';
  return key === 'o' ? 'column' : undefined;
}

function splitShortcutLabel(axis: TerminalSplitAxis) {
  const platform = terminalShortcutPlatform();
  if (platform === 'macos') return axis === 'row' ? '⌘D' : '⇧⌘D';
  if (platform === 'windows') return axis === 'row' ? 'Alt+Shift+=' : 'Alt+Shift+-';
  return axis === 'row' ? 'Ctrl+Shift+E' : 'Ctrl+Shift+O';
}

export function TerminalWorkspace({ visible, tab, loading, detectedAgents, terminalTitles, agentProcesses = {}, onTabChange, onTabClosed, onPaneStatus, onReload }: Props) {
  const { confirm, confirmationDialog } = useConfirmation();
  const [layout, setLayout] = useState<TerminalLayout | null>(() => tab ? fallbackLayout(tab) : null);
  const [activePaneId, setActivePaneId] = useState<string>();
  const [draggingPaneId, setDraggingPaneId] = useState<string>();
  const [paneDropTarget, setPaneDropTarget] = useState<PaneDropTarget>();
  const [maximizedPaneIds, setMaximizedPaneIds] = useState<Record<string, string>>({});
  const [error, setError] = useState('');
  const [operation, setOperation] = useState('');
  const layoutRef = useRef(layout);
  const draggingPaneIdRef = useRef<string | undefined>(undefined);
  const tabRef = useRef(tab);
  const revisionRef = useRef(tab?.revision);
  const saveTimerRef = useRef<number | undefined>(undefined);
  const savingRef = useRef(false);
  const pendingLayoutRef = useRef<TerminalLayout | undefined>(undefined);
  const flushRequestedRef = useRef(false);
  const lastSaveRef = useRef(0);
  const saveEpochRef = useRef(0);
  const terminalWorkspace = useRef<HTMLElement>(null);

  layoutRef.current = layout;
  tabRef.current = tab;
  const maximizedPaneId = tab ? maximizedPaneIds[tab.id] : undefined;

  const setMaximizedPaneId = (
    tabId: string,
    update: string | undefined | ((current: string | undefined) => string | undefined),
  ) => {
    setMaximizedPaneIds((current) => {
      const previous = current[tabId];
      const next = typeof update === 'function' ? update(previous) : update;
      if (next === previous) return current;
      if (next) return { ...current, [tabId]: next };
      if (!(tabId in current)) return current;
      const remaining = { ...current };
      delete remaining[tabId];
      return remaining;
    });
  };

  useEffect(() => {
    const next = tab ? fallbackLayout(tab) : null;
    setLayout(next);
    layoutRef.current = next;
    revisionRef.current = tab?.revision;
    const ids = paneIds(next);
    setActivePaneId((current) => current && ids.includes(current)
      ? current
      : maximizedPaneId && ids.includes(maximizedPaneId) ? maximizedPaneId : ids[0]);
    setDraggingPaneId(undefined);
    draggingPaneIdRef.current = undefined;
    setPaneDropTarget(undefined);
    setError('');
  }, [tab?.id, tab?.layout, tab?.revision]);

  useEffect(() => {
    saveEpochRef.current += 1;
    if (saveTimerRef.current !== undefined) {
      window.clearTimeout(saveTimerRef.current);
      saveTimerRef.current = undefined;
    }
    pendingLayoutRef.current = undefined;
    flushRequestedRef.current = false;
    savingRef.current = false;
  }, [tab?.id]);

  useEffect(() => {
    if (maximizedPaneId && ((tab?.panes.length ?? 0) <= 1
      || !tab?.panes.some((pane) => pane.id === maximizedPaneId))) {
      const tabId = tab?.id;
      if (tabId) setMaximizedPaneId(tabId, undefined);
    }
  }, [maximizedPaneId, tab?.panes]);

  useEffect(() => () => {
    if (saveTimerRef.current !== undefined) window.clearTimeout(saveTimerRef.current);
  }, []);

  const runLayoutSave = async () => {
    if (savingRef.current || !pendingLayoutRef.current) return;
    if (saveTimerRef.current !== undefined) {
      window.clearTimeout(saveTimerRef.current);
      saveTimerRef.current = undefined;
    }
    const currentTab = tabRef.current;
    const candidate = pendingLayoutRef.current;
    if (!currentTab) return;
    const saveEpoch = saveEpochRef.current;
    pendingLayoutRef.current = undefined;
    savingRef.current = true;
    lastSaveRef.current = Date.now();
    try {
      const updated = await terminalApi.updateLayout(currentTab.id, candidate, revisionRef.current);
      if (updated) {
        const stillActive = saveEpochRef.current === saveEpoch && tabRef.current?.id === currentTab.id;
        if (stillActive) revisionRef.current = updated.revision;
        onTabChange({ ...updated, layout: stillActive ? layoutRef.current ?? updated.layout : updated.layout });
      }
    } catch (reason) {
      if (saveEpochRef.current === saveEpoch) setError(`布局保存失败：${message(reason)}`);
    } finally {
      if (saveEpochRef.current !== saveEpoch) return;
      savingRef.current = false;
      if (pendingLayoutRef.current) {
        if (flushRequestedRef.current) {
          flushRequestedRef.current = false;
          void runLayoutSave();
        } else {
          const delay = Math.max(0, 250 - (Date.now() - lastSaveRef.current));
          saveTimerRef.current = window.setTimeout(() => void runLayoutSave(), delay);
        }
      } else {
        flushRequestedRef.current = false;
      }
    }
  };

  const queueLayoutSave = (next: TerminalLayout, flush = false) => {
    pendingLayoutRef.current = next;
    if (flush) flushRequestedRef.current = true;
    if (savingRef.current) return;
    if (flush) {
      void runLayoutSave();
      return;
    }
    if (saveTimerRef.current !== undefined) return;
    const delay = Math.max(0, 250 - (Date.now() - lastSaveRef.current));
    saveTimerRef.current = window.setTimeout(() => void runLayoutSave(), delay);
  };

  const resizeSplit = (event: ReactPointerEvent<HTMLDivElement>, axis: TerminalSplitAxis, path: number[]) => {
    const divider = event.currentTarget;
    const container = divider.parentElement;
    if (!container || !layoutRef.current) return;
    event.preventDefault();
    const pointerId = event.pointerId;
    divider.setPointerCapture(pointerId);
    document.body.classList.add(axis === 'row' ? 'resizing-terminal-row' : 'resizing-terminal-column');

    const update = (clientX: number, clientY: number) => {
      const bounds = container.getBoundingClientRect();
      const raw = axis === 'row'
        ? (clientX - bounds.left) / bounds.width
        : (clientY - bounds.top) / bounds.height;
      const ratio = Math.min(.9, Math.max(.1, raw));
      const current = layoutRef.current;
      if (!current) return;
      const next = replaceRatio(current, path, ratio);
      layoutRef.current = next;
      setLayout(next);
      queueLayoutSave(next);
    };
    const move = (moveEvent: PointerEvent) => update(moveEvent.clientX, moveEvent.clientY);
    const stop = (stopEvent: PointerEvent) => {
      update(stopEvent.clientX, stopEvent.clientY);
      window.removeEventListener('pointermove', move);
      window.removeEventListener('pointerup', stop);
      window.removeEventListener('pointercancel', stop);
      document.body.classList.remove('resizing-terminal-row', 'resizing-terminal-column');
      if (divider.hasPointerCapture(pointerId)) divider.releasePointerCapture(pointerId);
      if (layoutRef.current) queueLayoutSave(layoutRef.current, true);
    };
    window.addEventListener('pointermove', move);
    window.addEventListener('pointerup', stop, { once: true });
    window.addEventListener('pointercancel', stop, { once: true });
  };

  const finishPaneDrag = () => {
    draggingPaneIdRef.current = undefined;
    setDraggingPaneId(undefined);
    setPaneDropTarget(undefined);
  };

  const startPaneDrag = (event: ReactDragEvent<HTMLElement>, paneId: string) => {
    if (operation || tab?.panes.length === 1 || (event.target as HTMLElement).closest('button')) {
      event.preventDefault();
      return;
    }
    setActivePaneId(paneId);
    draggingPaneIdRef.current = paneId;
    setDraggingPaneId(paneId);
    setPaneDropTarget(undefined);
    event.dataTransfer.effectAllowed = 'move';
    event.dataTransfer.setData('application/x-aow-terminal-pane', paneId);
    event.dataTransfer.setData('text/plain', paneId);
  };

  const updatePaneDropTarget = (event: ReactDragEvent<HTMLElement>, targetPaneId: string) => {
    const sourcePaneId = draggingPaneIdRef.current
      || event.dataTransfer.getData('application/x-aow-terminal-pane');
    if (!sourcePaneId || sourcePaneId === targetPaneId || operation) {
      setPaneDropTarget((current) => current?.paneId === targetPaneId ? undefined : current);
      return;
    }
    event.preventDefault();
    event.dataTransfer.dropEffect = 'move';
    const direction = paneDropDirection(event);
    setPaneDropTarget((current) => current?.paneId === targetPaneId && current.direction === direction
      ? current
      : { paneId: targetPaneId, direction });
  };

  const dropPane = (event: ReactDragEvent<HTMLElement>, targetPaneId: string) => {
    event.preventDefault();
    event.stopPropagation();
    const sourcePaneId = draggingPaneIdRef.current
      || event.dataTransfer.getData('application/x-aow-terminal-pane');
    const direction = paneDropDirection(event);
    const current = layoutRef.current;
    const next = current && sourcePaneId
      ? movePaneInLayout(current, sourcePaneId, targetPaneId, direction)
      : null;
    if (next) {
      layoutRef.current = next;
      setLayout(next);
      setActivePaneId(sourcePaneId);
      setError('');
      queueLayoutSave(next, true);
    }
    finishPaneDrag();
  };

  const split = async (pane: TerminalPane, axis: TerminalSplitAxis) => {
    if (!tab) return;
    setOperation(`split:${pane.id}`);
    setError('');
    try {
      const updated = await terminalApi.split(tab.id, pane.id, axis, {
        cwd: pane.cwd || undefined,
        shell: pane.kind === 'terminal' ? pane.shell || undefined : undefined,
      });
      if (updated) {
        onTabChange(updated);
        const ids = paneIds(updated.layout);
        setActivePaneId(ids.find((id) => !tab.panes.some((oldPane) => oldPane.id === id)) ?? pane.id);
      } else {
        onReload();
      }
    } catch (reason) {
      setError(`分屏失败：${message(reason)}`);
    } finally {
      setOperation('');
    }
  };

  useEffect(() => {
    const splitWithShortcut = (event: KeyboardEvent) => {
      if (
        event.repeat
        || !visible
        || operation
        || !terminalWorkspace.current?.contains(event.target as Node)
        || !(document.activeElement instanceof Element && document.activeElement.closest('.terminal-emulator'))
      ) return;

      const axis = splitShortcutAxis(event, terminalShortcutPlatform());
      const pane = activePaneId ? tab?.panes.find((item) => item.id === activePaneId) : undefined;
      if (!axis || !pane) return;

      event.preventDefault();
      void split(pane, axis);
    };

    window.addEventListener('keydown', splitWithShortcut, true);
    return () => window.removeEventListener('keydown', splitWithShortcut, true);
  }, [activePaneId, operation, tab, visible]);

  const togglePaneMaximized = (pane: TerminalPane) => {
    if (!tab || operation) return;
    setActivePaneId(pane.id);
    setDraggingPaneId(undefined);
    draggingPaneIdRef.current = undefined;
    setPaneDropTarget(undefined);
    setMaximizedPaneId(tab.id, (current) => current === pane.id ? undefined : pane.id);
  };

  const selectMaximizedPane = (paneId: string) => {
    if (!tab || !maximizedPaneId || paneId === maximizedPaneId) return;
    setActivePaneId(paneId);
    setMaximizedPaneId(tab.id, paneId);
  };

  const closePane = async (pane: TerminalPane) => {
    if (!tab) return;
    const closingLastPane = tab.panes.length === 1;
    if (!await confirm({
      title: closingLastPane ? '关闭终端？' : '关闭终端窗口？',
      description: closingLastPane
        ? `这是“${tab.name}”的最后一个窗口，关闭后也会关闭对应的终端标签页。`
        : '将关闭以下终端窗口。',
      items: [{ id: pane.id, label: terminalPaneTitle(pane, detectedAgents, terminalTitles), detail: pane.cwd, icon: <SquareTerminal /> }],
      warning: '此窗口中仍在运行的命令将被终止，此操作无法撤销。',
      confirmLabel: closingLastPane ? '关闭终端' : '关闭窗口',
      danger: true,
    })) return;
    if (tabRef.current?.id !== tab.id || !tabRef.current.panes.some((item) => item.id === pane.id)) return;
    setOperation(`close:${pane.id}`);
    setError('');
    try {
      const updated = await terminalApi.closePane(tab.id, pane.id);
      if (updated) {
        if (maximizedPaneId === pane.id) {
          const currentIds = paneIds(layoutRef.current);
          const closedIndex = currentIds.indexOf(pane.id);
          const remainingIds = paneIds(fallbackLayout(updated));
          const nextPaneId = remainingIds[Math.min(Math.max(closedIndex, 0), remainingIds.length - 1)];
          setMaximizedPaneId(tab.id, updated.panes.length > 1 ? nextPaneId : undefined);
          setActivePaneId(nextPaneId);
        }
        onTabChange(updated);
      } else {
        setMaximizedPaneId(tab.id, undefined);
        onTabClosed(tab.id);
      }
    } catch (reason) {
      setError(`关闭 pane 失败：${message(reason)}`);
    } finally {
      setOperation('');
    }
  };

  const markStatus = (paneId: string, status: TerminalPaneStatus, exitCode?: number | null) => {
    const currentTab = tabRef.current;
    if (currentTab) {
      onPaneStatus(currentTab.id, paneId, status, exitCode);
      onReload();
    }
  };

  const naturalPaneOrder = paneIds(layout).filter((id) => tab?.panes.some((pane) => pane.id === id));

  const renderLayout = (node: TerminalLayout, path: number[] = []): ReactNode => {
    if (node.type === 'pane') {
      const pane = tab?.panes.find((item) => item.id === node.pane_id);
      if (!pane) return <div className="terminal-pane-missing">Pane {node.pane_id} 不存在</div>;
      const agentId = terminalPaneAgent(pane, detectedAgents);
      const title = terminalPaneTitle(pane, detectedAgents, terminalTitles);
      const paneBusy = operation.endsWith(`:${pane.id}`);
      const paneMaximized = maximizedPaneId === pane.id;
      const paneObscured = Boolean(maximizedPaneId && !paneMaximized);
      const paneDraggable = !operation && !maximizedPaneId && tab!.panes.length > 1;
      const dropDirection = paneDropTarget?.paneId === pane.id ? paneDropTarget.direction : undefined;
      return (
        <section
          key={pane.id}
          className={[
            'terminal-pane',
            activePaneId === pane.id ? 'active' : '',
            paneMaximized ? 'maximized' : '',
            paneObscured ? 'pane-obscured' : '',
            draggingPaneId === pane.id ? 'pane-dragging' : '',
            dropDirection ? `pane-drop-target drop-${dropDirection}` : '',
          ].filter(Boolean).join(' ')}
          data-drop-label={dropDirection ? paneDropLabels[dropDirection] : undefined}
          aria-hidden={paneObscured || undefined}
          onPointerDown={() => setActivePaneId(pane.id)}
          onDragOver={(event) => updatePaneDropTarget(event, pane.id)}
          onDrop={(event) => dropPane(event, pane.id)}
        >
          <TerminalAgentPane tabId={tab!.id} paneId={pane.id} agentId={agentId}
            title={terminalTitles[pane.id] ?? ''} cwd={pane.cwd} process={agentProcesses[pane.id]}
            visible={visible && !paneObscured}
            header={sessionButton => <header
            className={`terminal-pane-header ${paneDraggable ? 'draggable' : ''}`}
            draggable={paneDraggable}
            onDragStart={(event) => startPaneDrag(event, pane.id)}
            onDragEnd={finishPaneDrag}
          >
            <GripVertical className="terminal-pane-drag-handle" aria-label="拖动 pane 调整布局" />
            <TerminalLifecycleDot className="terminal-pane-status" state={terminalPaneLifecycle(pane)} />
            {agentId ? <AgentIcon agentId={agentId} /> : <SquareTerminal />}
            <span className="terminal-pane-name" title={`${title}\n路径：${pane.cwd || '未知'}`}>
              {title}
            </span>
            <span className="terminal-pane-shell">{pane.shell}</span>
            {sessionButton}
            <button title={`向右分屏（${splitShortcutLabel('row')}）`} aria-label="向右分屏" disabled={paneBusy} onClick={() => void split(pane, 'row')}><Columns2 /></button>
            <button title={`向下分屏（${splitShortcutLabel('column')}）`} aria-label="向下分屏" disabled={paneBusy} onClick={() => void split(pane, 'column')}><Rows2 /></button>
            {tab!.panes.length > 1 ? (
              <button
                title={paneMaximized ? '恢复布局' : '最大化 shell 窗口'}
                aria-label={paneMaximized ? '恢复布局' : '最大化 shell 窗口'}
                aria-pressed={paneMaximized}
                disabled={paneBusy}
                onClick={() => togglePaneMaximized(pane)}
              >
                {paneMaximized ? <Minimize2 /> : <Maximize2 />}
              </button>
            ) : null}
            <button title="关闭 pane" aria-label="关闭 pane" disabled={paneBusy} onClick={() => void closePane(pane)}>{paneBusy ? <LoaderCircle className="spinning" /> : <X />}</button>
          </header>}
            terminal={terminalVisible => <TerminalInputPane key={`${tab!.id}:${pane.id}`} visible={terminalVisible} tabId={tab!.id} pane={pane} active={activePaneId === pane.id} onFocus={() => setActivePaneId(pane.id)} onStatus={(status, code) => markStatus(pane.id, status, code)} />}
          />
        </section>
      );
    }
    const direction = node.axis === 'row' ? 'horizontal' : 'vertical';
    return (
      <div className={`terminal-split ${direction}`}>
        <div className="terminal-split-child" style={{ flexBasis: `${node.ratio * 100}%` }}>{renderLayout(node.first, [...path, 0])}</div>
        <div
          className={`terminal-split-divider ${direction}`}
          role="separator"
          aria-orientation={node.axis === 'row' ? 'vertical' : 'horizontal'}
          aria-valuemin={10}
          aria-valuemax={90}
          aria-valuenow={Math.round(node.ratio * 100)}
          onPointerDown={(event) => resizeSplit(event, node.axis, path)}
        />
        <div className="terminal-split-child" style={{ flexBasis: `${(1 - node.ratio) * 100}%` }}>{renderLayout(node.second, [...path, 1])}</div>
      </div>
    );
  };

  if (loading && !tab) {
    return <main className="terminal-workspace terminal-workspace-empty">{confirmationDialog}<LoaderCircle className="spinning" /><span>正在加载终端…</span></main>;
  }
  if (!tab) {
    return (
      <main className="terminal-workspace terminal-workspace-empty">
        {confirmationDialog}
        <div className="terminal-empty-guide">
          <h2>Terminal</h2>
          <p>从左侧新建一个终端，并通过终端标签页菜单修改窗口名称。</p>
        </div>
      </main>
    );
  }
  return (
    <main ref={terminalWorkspace} className="terminal-workspace">
      {confirmationDialog}
      {error ? <div className="terminal-workspace-error" role="alert">{error}<button onClick={() => setError('')}>关闭</button></div> : null}
      {maximizedPaneId ? (
        <nav className="terminal-pane-tabs-shell" aria-label="Terminal 窗口">
          <div className="terminal-pane-tabs" role="tablist">
            {naturalPaneOrder.map((paneId) => {
              const pane = tab.panes.find((item) => item.id === paneId);
              if (!pane) return null;
              const agentId = terminalPaneAgent(pane, detectedAgents);
              const title = terminalPaneTitle(pane, detectedAgents, terminalTitles);
              const selected = pane.id === maximizedPaneId;
              return (
                <button
                  key={pane.id}
                  type="button"
                  role="tab"
                  className={selected ? 'active' : ''}
                  aria-selected={selected}
                  title={`${title}\n${pane.cwd || '未知路径'}`}
                  onClick={() => selectMaximizedPane(pane.id)}
                >
                  <TerminalLifecycleDot className="terminal-pane-status" state={terminalPaneLifecycle(pane)} />
                  {agentId ? <AgentIcon agentId={agentId} /> : <SquareTerminal />}
                  <span>{title}</span>
                </button>
              );
            })}
          </div>
        </nav>
      ) : null}
      <div
        className={`terminal-layout ${maximizedPaneId ? 'pane-maximized' : ''}`}
        onDragOver={(event) => {
          if (!(event.target as Element).closest('.terminal-pane')) setPaneDropTarget(undefined);
        }}
        onDragLeave={(event) => {
          const next = event.relatedTarget;
          if (!(next instanceof Node) || !event.currentTarget.contains(next)) setPaneDropTarget(undefined);
        }}
      >
        {layout ? renderLayout(layout) : <div className="terminal-workspace-empty">这个终端没有可用的 pane。</div>}
      </div>
    </main>
  );
}

